 说明： process 对象是一个全局对象（无需 require），提供有关当前 Node.js 进程的信息并对其进行控制。 常用属性/方法： process.argv: 返回一个数组，包含启动 Node.js 进程时的命令行参数。第一个元素是 node 可执行文件路径，第二个元素是当前 JS 文件路径，后续元素是传递的其他参数。process.env: 返回一个包含用户环境信息的对象（如 PATH, HOME）。注意： 敏感信息（如 API 密钥）应通过更安全的方式管理，而不是直接硬编码或放在 .env 文件中提交。process.cwd(): 返回当前 Node.js 进程的工作目录。process.pid: 当前进程的 ID。process.platform: 返回运行进程的操作系统平台（同 os.platform()）。process.arch: 返回运行进程的 CPU 架构（同 os.arch()）。process.version: Node.js 版本字符串。process.versions: 包含 Node.js 及其依赖（如 V8, libuv, OpenSSL）版本信息的对象。process.exit([code]): 以指定的状态码 code 退出当前进程（0 表示成功，非 0 表示错误）。process.nextTick(callback[, ...args]): 将回调函数添加到 nextTick 队列，在当前操作完成后、事件循环下一阶段开始前执行。process.on(eventName, listener): 监听进程事件，如： 'exit': 进程即将退出时触发（在此回调中不能执行异步操作）。'uncaughtException': 当一个未被捕获的 JavaScript 异常冒泡回事件循环时触发。不推荐用它来恢复应用正常运行，主要用于执行同步清理或记录日志。'unhandledRejection': 当一个 Promise 被 reject 且没有 catch 处理时触发。信号事件 (如 'SIGINT', 'SIGTERM'): 处理操作系统信号。 process.stdout, process.stderr, process.stdin: 分别代表标准输出、标准错误、标准输入的流对象。console.log 内部就是使用 process.stdout。 示例： // 获取命令行参数 console.log(&quot;Command line arguments:&quot;, process.argv); // Run: node your_script.js arg1 arg2 // Output: [ '/path/to/node', '/path/to/your_script.js', 'arg1', 'arg2' ] // 获取环境变量 console.log( &quot;Current PATH:&quot;, process.env.PATH ? process.env.PATH.substring(0, 50) + &quot;...&quot; : &quot;N/A&quot; ); console.log(&quot;NODE_ENV:&quot;, process.env.NODE_ENV || &quot;development&quot;); // 常用于区分环境 // 获取进程信息 console.log(&quot;Current working directory:&quot;, process.cwd()); console.log(&quot;Process ID:&quot;, process.pid); console.log(&quot;Node.js version:&quot;, process.version); // console.log('All versions:', process.versions); // 监听退出事件 process.on(&quot;exit&quot;, (code) =&gt; { // 只能执行同步操作 console.log(`
Process exiting with code: ${code}`); }); // 监听未捕获异常 (应谨慎使用) process.on(&quot;uncaughtException&quot;, (err, origin) =&gt; { console.error(`
Caught exception: ${err}
Exception origin: ${origin}`); // 在这里记录日志、清理资源，然后通常应该退出 process.exit(1); // 强制退出 }); // 监听未处理的 Promise rejection process.on(&quot;unhandledRejection&quot;, (reason, promise) =&gt; { console.error(&quot;
Unhandled Rejection at:&quot;, promise, &quot;reason:&quot;, reason); // 记录日志，可能也需要退出 // process.exit(1); }); // 模拟未捕获异常 // throw new Error('This is an uncaught exception!'); // 模拟未处理的 rejection // Promise.reject(new Error('This is an unhandled rejection!')); // 正常退出 (如果上面的模拟被注释掉) // setTimeout(() =&gt; { // console.log('
Exiting normally...'); // process.exit(0); // }, 1000); console.log(&quot;Script continues...&quot;);

 说明： Node.js 是单线程的（指 JS 执行），为了充分利用多核 CPU 或执行外部命令，child_process 模块允许你创建子进程。 创建子进程的方式： child_process.exec(command[, options][, callback]): 启动一个 shell 来执行 command。它会缓冲命令的输出，并在子进程完成后通过回调函数一次性返回 stdout 和 stderr。适合执行简单的命令，但对大量输出不友好（可能耗尽内存）。child_process.execFile(file[, args][, options][, callback]): 类似 exec，但不启动 shell，直接执行 file。更安全高效，适合执行特定可执行文件。child_process.spawn(command[, args][, options]): 启动一个新进程来执行 command。它不缓冲输出，而是通过流（stdout, stderr）来处理输入输出。适合处理大量数据或需要与子进程持续交互的场景。返回一个 ChildProcess 实例。child_process.fork(modulePath[, args][, options]): spawn 的特殊形式，专门用于创建新的 Node.js 进程。父子进程之间可以通过 send() 方法和 message 事件建立 IPC (Inter-Process Communication) 通道进行通信。 ChildProcess 实例事件/属性： stdout: 子进程的标准输出流 (Readable Stream)。stderr: 子进程的标准错误流 (Readable Stream)。stdin: 子进程的标准输入流 (Writable Stream)。pid: 子进程的 PID。on('message', (message) =&gt; ...): (仅 fork) 接收子进程通过 process.send() 发送的消息。on('error', (error) =&gt; ...): 进程无法被衍生或被杀死时触发。on('exit', (code, signal) =&gt; ...): 子进程退出时触发。on('close', (code, signal) =&gt; ...): 子进程所有 stdio 流都关闭后触发。send(message): (仅 fork) 向子进程发送消息。kill([signal]): 向子进程发送信号（默认 'SIGTERM'）。 示例： const { exec, spawn } = require(&quot;child_process&quot;); // 1. 使用 exec (简单命令，缓冲输出) console.log(&quot;--- Using exec ---&quot;); exec(&quot;ls -lh /usr&quot;, (error, stdout, stderr) =&gt; { if (error) { console.error(`exec error: ${error}`); return; } if (stderr) { console.error(`exec stderr: ${stderr}`); } console.log( `exec stdout (first 200 chars):
${stdout.substring(0, 200)}...` ); }); // 2. 使用 spawn (流式处理，适合大数据/交互) console.log(&quot;
--- Using spawn ---&quot;); const findProcess = spawn(&quot;find&quot;, [__dirname, &quot;-type&quot;, &quot;f&quot;]); // 执行 find 命令 let fileCount = 0; // 监听 stdout 流 findProcess.stdout.on(&quot;data&quot;, (data) =&gt; { const lines = data .toString() .split(&quot;
&quot;) .filter((line) =&gt; line.length &gt; 0); fileCount += lines.length; console.log(`spawn stdout chunk:
${lines.join(&quot;
&quot;)}`); }); // 监听 stderr 流 findProcess.stderr.on(&quot;data&quot;, (data) =&gt; { console.error(`spawn stderr: ${data}`); }); // 监听错误事件 findProcess.on(&quot;error&quot;, (err) =&gt; { console.error(&quot;Failed to start subprocess.&quot;, err); }); // 监听退出事件 findProcess.on(&quot;exit&quot;, (code, signal) =&gt; { if (code !== null) { console.log(`
spawn process exited with code ${code}`); console.log(`Total files found: ${fileCount}`); } else if (signal !== null) { console.log(`
spawn process killed with signal ${signal}`); } }); // // 3. 使用 fork (Node.js 子进程与 IPC 通信) // console.log('
--- Using fork ---'); // const worker = fork(require.resolve('./worker.js')); // 使用 require.resolve 获取绝对路径 // worker.on('message', (msg) =&gt; { // console.log('Message from worker:', msg); // if (msg.type === 'done') { // worker.kill(); // 任务完成，结束子进程 // } // }); // worker.on('exit', (code) =&gt; { // console.log(`Worker process exited with code ${code}`); // }); // worker.send({ type: 'start', payload: 10 }); // 向子进程发送消息 // // worker.js (子进程文件) // process.on('message', (msg) =&gt; { // console.log('[Worker] Received message:', msg); // if (msg.type === 'start') { // let result = 0; // for (let i = 0; i &lt; msg.payload * 100000000; i++) { // 模拟耗时计算 // result += i; // } // process.send({ type: 'done', result }); // 向父进程发送结果 // } // });

 if-elif-else 条件语句​  说明: 根据条件的真假执行不同的代码块。elif (else if) 可以有多个，else 是可选的。 示例: score = 75 if score &gt;= 90: grade = 'A' print(&quot;优秀！&quot;) elif score &gt;= 80: grade = 'B' print(&quot;良好！&quot;) elif score &gt;= 60: grade = 'C' print(&quot;及格！&quot;) else: grade = 'D' print(&quot;需要努力！&quot;) print(f&quot;分数 {score} 对应的等级是: {grade}&quot;) # 输出: # 及格！ # 分数 75 对应的等级是: C   while 循环​  说明: 当指定条件为 True 时，重复执行代码块。需要注意避免无限循环。 示例: count = 0 # 当 count 小于 5 时，循环继续 while count &lt; 5: print(f&quot;当前 count: {count}&quot;) count += 1 # 更新循环变量，否则会无限循环 print(&quot;while 循环结束&quot;) # 输出: # 当前 count: 0 # 当前 count: 1 # 当前 count: 2 # 当前 count: 3 # 当前 count: 4 # while 循环结束   for 循环(迭代器协议)​  说明: 用于遍历可迭代对象（如 list, tuple, str, set, dict, range 对象等）中的元素。Python 的 for 循环本质上是使用了迭代器协议 (__iter__() 和 __next__())。 示例: # 遍历列表 fruits = [&quot;苹果&quot;, &quot;香蕉&quot;, &quot;橙子&quot;] print(&quot;遍历水果列表:&quot;) for fruit in fruits: print(fruit) # 遍历字符串 print(&quot;
遍历字符串:&quot;) for char in &quot;Python&quot;: print(char) # 遍历 range 对象 (生成一系列数字) print(&quot;
遍历 range(5):&quot;) for i in range(5): # 生成 0, 1, 2, 3, 4 print(i) # 遍历字典 (默认遍历键) print(&quot;
遍历字典的键:&quot;) my_dict = {'a': 1, 'b': 2} for key in my_dict: print(key) # 遍历字典的值 print(&quot;
遍历字典的值:&quot;) for value in my_dict.values(): print(value) # 遍历字典的键值对 print(&quot;
遍历字典的键值对:&quot;) for key, value in my_dict.items(): print(f&quot;{key}: {value}&quot;)   break, continue, pass​  说明: break: 立即终止当前所在的循环（for 或 while）。continue: 跳过当前循环的剩余部分，直接进入下一次迭代。pass: 空语句，用作占位符，不做任何事情。通常用于语法上需要语句但逻辑上不需要执行任何操作的地方。 示例: print(&quot;--- break 示例 ---&quot;) for i in range(10): if i == 5: print(&quot;遇到 5，循环中断&quot;) break # 当 i 等于 5 时，退出循环 print(i) # 输出: 0 1 2 3 4 遇到 5，循环中断 print(&quot;
--- continue 示例 ---&quot;) for i in range(5): if i % 2 == 0: # 如果 i 是偶数 print(f&quot;跳过偶数 {i}&quot;) continue # 跳过本次循环的 print(i) print(f&quot;处理奇数 {i}&quot;) # 输出: # 跳过偶数 0 # 处理奇数 1 # 跳过偶数 2 # 处理奇数 3 # 跳过偶数 4 print(&quot;
--- pass 示例 ---&quot;) for i in range(3): if i == 1: pass # 占位符，什么也不做 print(&quot;i 等于 1 时执行了 pass&quot;) else: print(f&quot;i = {i}&quot;) # 输出: # i = 0 # i 等于 1 时执行了 pass # i = 2 def my_function(): # TODO: 以后实现这个函数 pass # 暂时用 pass 占位，使得函数定义在语法上完整   三元表达式​  说明: 一种简洁的条件赋值语句，格式为 value_if_true if condition else value_if_false。 示例: age = 20 # 如果 age &gt;= 18，则 status 为 &quot;成年&quot;，否则为 &quot;未成年&quot; status = &quot;成年&quot; if age &gt;= 18 else &quot;未成年&quot; print(f&quot;年龄 {age} 的状态是: {status}&quot;) # 输出: 年龄 20 的状态是: 成年 is_even = &quot;偶数&quot; if age % 2 == 0 else &quot;奇数&quot; print(f&quot;{age} 是: {is_even}&quot;) # 输出: 20 是: 偶数

 try-except-else-finally​  说明: 用于处理代码执行期间可能发生的错误（异常）。 try: 包含可能引发异常的代码块。except: 捕获并处理特定类型的异常。可以有多个 except 块来处理不同类型的异常，或者一个 except 块处理多种异常 except (TypeError, ValueError):，或者捕获所有异常 except Exception:.else: （可选）如果 try 块中没有发生任何异常，则执行 else 块。finally: （可选）无论 try 块中是否发生异常，finally 块中的代码总是会被执行（通常用于资源清理）。 示例: try: numerator = int(input(&quot;输入分子: &quot;)) denominator = int(input(&quot;输入分母: &quot;)) result = numerator / denominator except ValueError: print(&quot;错误：输入必须是整数！&quot;) except ZeroDivisionError: print(&quot;错误：分母不能为零！&quot;) except Exception as e: # 捕获其他所有类型的异常 print(f&quot;发生了未知错误: {e}&quot;) print(f&quot;错误类型: {type(e)}&quot;) else: # 如果 try 块没有异常，则执行这里 print(f&quot;计算结果: {result}&quot;) finally: # 无论是否有异常，都会执行这里 print(&quot;计算结束。&quot;)   常见内置异常类型​  说明: Python 有许多内置的异常类型，表示不同类型的错误。 Exception: 几乎所有内置非系统退出异常的基类。AttributeError: 访问对象不存在的属性或方法。ImportError: 无法导入模块或包。IndexError: 序列索引超出范围。KeyError: 字典中查找不存在的键。NameError: 使用未定义的变量。TypeError: 对类型无效的操作（如 len(10)）。ValueError: 函数接收到类型正确但值不合适的参数（如 int('abc')）。ZeroDivisionError: 除数为零。FileNotFoundError: 试图打开不存在的文件。 示例: my_list = [1, 2] my_dict = {'a': 1} try: # print(undefined_variable) # NameError # print(my_list[5]) # IndexError # print(my_dict['b']) # KeyError # result = 'a' + 5 # TypeError # num = int('xyz') # ValueError # f = open('nonexistent.txt') # FileNotFoundError # import non_existent_module # ImportError pass # 取消注释以上行来触发对应的异常 except NameError: print(&quot;捕获到 NameError&quot;) except IndexError: print(&quot;捕获到 IndexError&quot;) except KeyError: print(&quot;捕获到 KeyError&quot;) except TypeError: print(&quot;捕获到 TypeError&quot;) except ValueError: print(&quot;捕获到 ValueError&quot;) except FileNotFoundError: print(&quot;捕获到 FileNotFoundError&quot;) except ImportError: print(&quot;捕获到 ImportError&quot;) except Exception as e: print(f&quot;捕获到其他异常: {type(e).__name__}&quot;)   raise 抛出异常​  说明: 使用 raise 语句可以手动触发一个异常。可以抛出内置异常的实例，也可以抛出自定义异常的实例。 示例: def check_age(age): if age &lt; 0: # 抛出一个 ValueError 异常 raise ValueError(&quot;年龄不能为负数！&quot;) elif age &lt; 18: print(&quot;未成年&quot;) else: print(&quot;成年&quot;) try: check_age(25) # 输出: 成年 check_age(-5) # 触发 ValueError except ValueError as e: print(f&quot;捕获到错误: {e}&quot;) # 输出: 捕获到错误: 年龄不能为负数！ # 也可以不带参数地在 except 块中重新抛出捕获到的异常 try: result = 10 / 0 except ZeroDivisionError: print(&quot;在 except 块中检测到 ZeroDivisionError，重新抛出&quot;) raise # 重新抛出 ZeroDivisionError   自定义异常类​  说明: 通过继承 Exception 类（或其子类）来创建自己的异常类型。这有助于更精确地表达代码中特定类型的错误。 示例: # 定义一个自定义异常类 class InsufficientBalanceError(Exception): &quot;&quot;&quot;表示账户余额不足的异常&quot;&quot;&quot; def __init__(self, current_balance, needed_amount): self.current_balance = current_balance self.needed_amount = needed_amount # 自定义错误消息 message = f&quot;余额不足。当前余额: {current_balance}, 需要: {needed_amount}&quot; super().__init__(message) # 调用父类的构造函数 def withdraw(balance, amount): if amount &gt; balance: # 抛出自定义异常 raise InsufficientBalanceError(balance, amount) else: print(f&quot;成功取款 {amount}&quot;) return balance - amount account_balance = 100 try: account_balance = withdraw(account_balance, 50) # 成功 account_balance = withdraw(account_balance, 80) # 失败，抛出 InsufficientBalanceError except InsufficientBalanceError as e: print(f&quot;取款失败: {e}&quot;) # 可以访问自定义异常的属性 print(f&quot;详情 - 当前余额: {e.current_balance}, 尝试取款: {e.needed_amount}&quot;) # 输出: # 成功取款 50 # 取款失败: 余额不足。当前余额: 50, 需要: 80 # 详情 - 当前余额: 50, 尝试取款: 80   with 上下文管理器​  说明: with 语句用于简化资源管理（如文件、网络连接、锁等），确保资源在使用完毕后能够被正确地释放（即使发生异常）。它依赖于上下文管理器协议，即对象需要实现 __enter__() 和 __exit__() 方法。__enter__ 在进入 with 块时调用，__exit__ 在退出 with 块时调用（处理清理工作和异常）。 示例: # 使用 with 打开文件（常见用法） try: # 'w' 模式表示写入，如果文件存在则覆盖，不存在则创建 with open('example.txt', 'w', encoding='utf-8') as f: f.write(&quot;这是第一行。
&quot;) f.write(&quot;这是第二行。
&quot;) # 在这里模拟一个错误 # result = 1 / 0 print(&quot;文件写入成功 (在 with 块内)&quot;) # 文件在退出 with 块时自动关闭，即使发生错误 print(&quot;文件已自动关闭&quot;) except Exception as e: print(f&quot;在 with 块中发生错误: {e}&quot;) print(&quot;即使发生错误，文件也已自动关闭&quot;) # 读取文件内容 try: with open('example.txt', 'r', encoding='utf-8') as f: content = f.read() print(&quot;
文件内容:&quot;) print(content) except FileNotFoundError: print(&quot;文件不存在！&quot;) # 自定义上下文管理器示例 (简单演示) import time class Timer: def __enter__(self): &quot;&quot;&quot;进入 with 块时记录开始时间&quot;&quot;&quot; self.start_time = time.time() print(&quot;计时开始...&quot;) return self # 返回的对象可以在 as 子句中使用 def __exit__(self, exc_type, exc_val, exc_tb): &quot;&quot;&quot;退出 with 块时计算并打印耗时&quot;&quot;&quot; self.end_time = time.time() elapsed_time = self.end_time - self.start_time print(f&quot;计时结束. 耗时: {elapsed_time:.4f} 秒&quot;) # exc_type, exc_val, exc_tb 包含异常信息（如果没有异常则为 None） # 返回 True 表示异常已被处理，不再向外传播；返回 False 或 None 表示异常继续传播 return False # 让异常（如果有）正常传播 print(&quot;
使用自定义计时器:&quot;) with Timer() as t: # t 接收 __enter__ 返回的 self print(&quot;执行一些操作...&quot;) time.sleep(0.5) # 模拟耗时操作 print(&quot;操作完成.&quot;) # 输出: # 使用自定义计时器: # 计时开始... # 执行一些操作... # 操作完成. # 计时结束. 耗时: 0.5xxx 秒

 函数定义与调用​  说明: 使用 def 关键字定义函数，后面跟函数名、括号 ()（可能包含参数）和冒号 :。函数体需要缩进。通过函数名加括号 () 来调用函数。 示例: # 定义一个简单的函数 def greet(): &quot;&quot;&quot;这是一个简单的问候函数&quot;&quot;&quot; print(&quot;Hello!&quot;) # 定义一个带参数的函数 def greet_user(name): &quot;&quot;&quot;根据提供的名字进行问候&quot;&quot;&quot; print(f&quot;Hello, {name}!&quot;) # 调用函数 greet() # 输出: Hello! greet_user(&quot;Alice&quot;) # 输出: Hello, Alice!   参数传递(位置参数、关键字参数)​  说明: 位置参数 (Positional Arguments): 调用函数时，根据参数在函数定义中的位置来传递值。关键字参数 (Keyword Arguments): 调用函数时，使用 参数名=值 的形式传递，顺序可以不按定义时的顺序。 示例: def describe_pet(animal_type, pet_name): &quot;&quot;&quot;描述宠物信息&quot;&quot;&quot; print(f&quot;我有一只{animal_type}。&quot;) print(f&quot;它的名字叫{pet_name}。&quot;) # 使用位置参数调用 (顺序必须匹配) print(&quot;--- 位置参数 ---&quot;) describe_pet(&quot;狗&quot;, &quot;旺财&quot;) # 输出: # 我有一只狗。 # 它的名字叫旺财。 # 使用关键字参数调用 (顺序可以任意) print(&quot;
--- 关键字参数 ---&quot;) describe_pet(pet_name=&quot;咪咪&quot;, animal_type=&quot;猫&quot;) # 输出: # 我有一只猫。 # 它的名字叫咪咪。 # 混合使用 (位置参数必须在关键字参数之前) print(&quot;
--- 混合参数 ---&quot;) describe_pet(&quot;仓鼠&quot;, pet_name=&quot;皮皮&quot;) # 输出: # 我有一只仓鼠。 # 它的名字叫皮皮。 # 错误调用：位置参数不能在关键字参数之后 # describe_pet(pet_name=&quot;球球&quot;, &quot;兔子&quot;) # 会报 SyntaxError   默认参数​  说明: 在函数定义时，可以为参数指定默认值。如果调用函数时没有为该参数提供值，则使用默认值。带默认值的参数必须放在所有不带默认值的参数之后。 重要提示: 默认参数的值在函数定义时被计算一次。如果默认值是可变对象（如列表、字典），可能会导致意外行为，因为所有调用都共享这一个对象。推荐使用 None 作为默认值，然后在函数体内检查并创建新对象。 示例: # animal_type 有默认值 '狗' def describe_pet_default(pet_name, animal_type='狗'): &quot;&quot;&quot;描述宠物信息，动物类型有默认值&quot;&quot;&quot; print(f&quot;我有一只{animal_type}。&quot;) print(f&quot;它的名字叫{pet_name}。&quot;) print(&quot;--- 使用默认参数 ---&quot;) describe_pet_default(&quot;旺财&quot;) # animal_type 使用默认值 '狗' # 输出: # 我有一只狗。 # 它的名字叫旺财。 print(&quot;
--- 提供非默认值 ---&quot;) describe_pet_default(&quot;咪咪&quot;, &quot;猫&quot;) # animal_type 被指定为 '猫' # 输出: # 我有一只猫。 # 它的名字叫咪咪。 # 错误的默认参数使用（可变对象） def add_item(item, my_list=[]): # my_list 的默认值 [] 只创建一次 my_list.append(item) return my_list print(&quot;
--- 可变默认参数问题 ---&quot;) list1 = add_item(1) print(list1) # 输出: [1] list2 = add_item(2) # list2 期望是 [2]，但实际会是 [1, 2] print(list2) # 输出: [1, 2] (共享了同一个列表对象) # 推荐的修正方法 def add_item_corrected(item, my_list=None): if my_list is None: my_list = [] # 在函数调用时创建新列表 my_list.append(item) return my_list print(&quot;
--- 修正后的可变默认参数 ---&quot;) list3 = add_item_corrected(1) print(list3) # 输出: [1] list4 = add_item_corrected(2) print(list4) # 输出: [2] (每次调用都使用新列表)   可变参数(*args, **kwargs)​  说明: 用于处理不确定数量的参数。 *args: 将接收到的多余的位置参数打包成一个元组 (tuple)。**kwargs: 将接收到的多余的关键字参数打包成一个字典 (dict)。 示例: # 同时使用普通参数、*args 和 **kwargs def process_data(required_arg, *args, **kwargs): &quot;&quot;&quot;处理一个必需参数、任意数量的位置参数和关键字参数&quot;&quot;&quot; print(f&quot;必需参数: {required_arg}&quot;) print(&quot;
位置参数 (*args):&quot;) if args: for i, arg in enumerate(args): print(f&quot; args[{i}]: {arg}&quot;) else: print(&quot; 没有提供额外的的位置参数&quot;) print(&quot;
关键字参数 (**kwargs):&quot;) if kwargs: for key, value in kwargs.items(): print(f&quot; {key}: {value}&quot;) else: print(&quot; 没有提供额外的关键字参数&quot;) print(&quot;--- 调用 process_data ---&quot;) process_data(100) # 只提供必需参数 print(&quot;
--- 调用 process_data (带 *args) ---&quot;) process_data(100, 'a', 'b', 3.14) # 100 是 required_arg, 'a', 'b', 3.14 被放入 args print(&quot;
--- 调用 process_data (带 **kwargs) ---&quot;) process_data(100, name=&quot;Alice&quot;, age=30) # name 和 age 被放入 kwargs print(&quot;
--- 调用 process_data (带 *args 和 **kwargs) ---&quot;) process_data(100, 'x', 'y', city=&quot;Beijing&quot;, country=&quot;China&quot;) # 'x', 'y' 放入 args, city, country 放入 kwargs # 输出示例 (部分): # --- 调用 process_data --- # 必需参数: 100 # 位置参数 (*args): # 没有提供额外的的位置参数 # 关键字参数 (**kwargs): # 没有提供额外的关键字参数 # # --- 调用 process_data (带 *args) --- # 必需参数: 100 # 位置参数 (*args): # args[0]: a # args[1]: b # args[2]: 3.14 # ...   返回值(多值返回)​  说明: 函数使用 return 语句返回值。如果 return 语句后没有值，或者函数没有 return 语句，则默认返回 None。一个函数可以通过返回一个元组 (tuple) 来实现“返回”多个值。 示例: # 返回单个值 def add(a, b): return a + b sum_result = add(5, 3) print(f&quot;和: {sum_result}&quot;) # 输出: 和: 8 # 不返回值 (隐式返回 None) def print_message(msg): print(msg) return_value = print_message(&quot;Hello&quot;) # 输出: Hello print(f&quot;print_message 的返回值: {return_value}&quot;) # 输出: print_message 的返回值: None # 返回多个值 (实际上是返回一个元组) def get_coordinates(): x = 10 y = 20 return x, y # 等价于 return (x, y) coords = get_coordinates() print(f&quot;坐标元组: {coords}&quot;) # 输出: 坐标元组: (10, 20) print(f&quot;类型: {type(coords)}&quot;) # 输出: 类型: &lt;class 'tuple'&gt; # 可以使用序列解包接收多个返回值 x_val, y_val = get_coordinates() print(f&quot;X 值: {x_val}, Y 值: {y_val}&quot;) # 输出: X 值: 10, Y 值: 20   函数文档字符串​  说明: 函数定义的第一行（紧跟 def 语句之后）可以用一个字符串字面量来作为函数的文档字符串（docstring）。它用于解释函数的功能、参数、返回值等。可以使用内置的 help() 函数或访问函数的 __doc__ 属性来查看文档字符串。推荐使用三引号 &quot;&quot;&quot; &quot;&quot;&quot; 定义多行文档字符串。 示例: def calculate_area(length: float, width: float) -&gt; float: &quot;&quot;&quot; 计算矩形的面积。 参数: length (float): 矩形的长度。 width (float): 矩形的宽度。 返回: float: 矩形的面积。 异常: ValueError: 如果长度或宽度为负数。 &quot;&quot;&quot; if length &lt; 0 or width &lt; 0: raise ValueError(&quot;长度和宽度不能为负数&quot;) return length * width # 查看文档字符串 print(&quot;--- 使用 help() 查看文档 ---&quot;) help(calculate_area) print(&quot;
--- 直接访问 __doc__ 属性 ---&quot;) print(calculate_area.__doc__) # 调用函数 area = calculate_area(10.5, 5.2) print(f&quot;
计算得到的面积: {area}&quot;)

 嵌套函数​  说明: 在一个函数内部定义另一个函数。内部函数可以访问外部函数的变量（形成闭包的基础）。内部函数默认只在外部函数作用域内可见。 示例: def outer_function(text): &quot;&quot;&quot;外部函数&quot;&quot;&quot; message = text # 外部函数的局部变量 def inner_function(): &quot;&quot;&quot;内部函数，可以访问外部函数的变量 message&quot;&quot;&quot; print(f&quot;内部函数打印: {message}&quot;) print(&quot;外部函数开始执行&quot;) inner_function() # 在外部函数内部调用内部函数 print(&quot;外部函数执行完毕&quot;) outer_function(&quot;你好，世界！&quot;) # 输出: # 外部函数开始执行 # 内部函数打印: 你好，世界！ # 外部函数执行完毕 # 尝试在外部调用内部函数会失败 (NameError) # inner_function() # 会报错 NameError: name 'inner_function' is not defined   闭包​  说明: 当一个嵌套函数（内部函数）引用了其外部作用域（外部函数）中的变量，并且外部函数返回了这个内部函数时，就形成了一个闭包。即使外部函数执行完毕，内部函数仍然可以访问和使用它被定义时所在的外部作用域中的变量。 示例: def make_multiplier(n): &quot;&quot;&quot;创建一个乘以 n 的乘法器函数 (闭包)&quot;&quot;&quot; def multiplier(x): &quot;&quot;&quot;这个内部函数 '记住' 了 n 的值&quot;&quot;&quot; return x * n return multiplier # 返回内部函数对象 # 创建一个乘以 3 的乘法器 times3 = make_multiplier(3) # 创建一个乘以 5 的乘法器 times5 = make_multiplier(5) # 调用闭包函数 print(f&quot;3 * 9 = {times3(9)}&quot;) # 输出: 3 * 9 = 27 print(f&quot;5 * 9 = {times5(9)}&quot;) # 输出: 5 * 9 = 45 print(f&quot;3 * -2 = {times3(-2)}&quot;) # 输出: 3 * -2 = -6 # 检查闭包捕获的自由变量 # print(times3.__closure__[0].cell_contents) # 可以看到捕获的 n=3   装饰器​  说明: 装饰器本质上是一个函数，它接收一个函数作为参数，并返回一个新的函数（通常是包装了原函数的函数）。它允许你在不修改原函数代码的情况下，增加额外的功能（如日志、计时、权限检查等）。使用 @decorator_name 语法糖可以方便地应用装饰器。 示例: import time import functools # 用于 functools.wraps def timer_decorator(func): &quot;&quot;&quot;一个简单的计时装饰器&quot;&quot;&quot; # @functools.wraps(func) 保留原函数的元信息(如名字, 文档字符串) @functools.wraps(func) def wrapper(*args, **kwargs): start_time = time.perf_counter() # 更精确的计时 result = func(*args, **kwargs) # 调用原函数 end_time = time.perf_counter() print(f&quot;函数 '{func.__name__}' 执行耗时: {end_time - start_time:.6f} 秒&quot;) return result return wrapper # 返回包装后的函数 def logger_decorator(func): &quot;&quot;&quot;一个简单的日志装饰器&quot;&quot;&quot; @functools.wraps(func) def wrapper(*args, **kwargs): print(f&quot;准备执行函数 '{func.__name__}'，参数: args={args}, kwargs={kwargs}&quot;) result = func(*args, **kwargs) print(f&quot;函数 '{func.__name__}' 执行完毕，返回值: {result}&quot;) return result return wrapper # 使用装饰器语法糖应用装饰器 (执行顺序从下往上) @timer_decorator # 第二层装饰 @logger_decorator # 第一层装饰 def slow_operation(duration, message=&quot;&quot;): &quot;&quot;&quot;模拟一个耗时操作&quot;&quot;&quot; print(f&quot;正在执行耗时操作 ({duration}秒)... {message}&quot;) time.sleep(duration) return f&quot;操作完成: {message}&quot; # 调用被装饰的函数 result = slow_operation(0.5, message=&quot;处理数据&quot;) print(f&quot;
最终结果: {result}&quot;) # 查看被装饰函数的元信息 print(f&quot;
函数名称: {slow_operation.__name__}&quot;) # 仍然是 slow_operation (因为用了 @wraps) print(f&quot;函数文档: {slow_operation.__doc__}&quot;) # 仍然是原文档字符串 # 输出示例: # 准备执行函数 'slow_operation'，参数: args=(0.5,), kwargs={'message': '处理数据'} # 正在执行耗时操作 (0.5秒)... 处理数据 # 函数 'slow_operation' 执行完毕，返回值: 操作完成: 处理数据 # 函数 'slow_operation' 执行耗时: 0.5xxxxx 秒 # # 最终结果: 操作完成: 处理数据 # # 函数名称: slow_operation # 函数文档: 模拟一个耗时操作   lambda 表达式​  说明: lambda 表达式用于创建小型、匿名的函数。它的语法是 lambda arguments: expression。表达式的结果就是函数的返回值。Lambda 函数通常用于需要一个简单函数作为参数的地方（如 sorted, map, filter）。 示例: # 定义一个 lambda 函数，计算平方 square = lambda x: x * x print(f&quot;5 的平方: {square(5)}&quot;) # 输出: 5 的平方: 25 # 定义一个 lambda 函数，计算两个数的和 add = lambda a, b: a + b print(f&quot;3 + 7 = {add(3, 7)}&quot;) # 输出: 3 + 7 = 10 # 在 sorted 函数中使用 lambda 作为 key points = [(1, 5), (3, 2), (5, 8), (2, 1)] # 按每个元组的第二个元素排序 sorted_points = sorted(points, key=lambda point: point[1]) print(f&quot;按 Y 坐标排序后的点: {sorted_points}&quot;) # 输出: 按 Y 坐标排序后的点: [(2, 1), (3, 2), (1, 5), (5, 8)] # 在 filter 函数中使用 lambda 过滤偶数 numbers = [1, 2, 3, 4, 5, 6] even_numbers = list(filter(lambda n: n % 2 == 0, numbers)) print(f&quot;列表中的偶数: {even_numbers}&quot;) # 输出: 列表中的偶数: [2, 4, 6] # 在 map 函数中使用 lambda 对每个元素求平方 squared_numbers = list(map(lambda n: n * n, numbers)) print(f&quot;列表中元素的平方: {squared_numbers}&quot;) # 输出: 列表中元素的平方: [1, 4, 9, 16, 25, 36]   生成器函数(yield)​  说明: 包含 yield 关键字的函数是一个生成器函数。调用生成器函数不会立即执行函数体，而是返回一个生成器对象（一种特殊的迭代器）。每次对生成器对象调用 next()（或在 for 循环中使用）时，函数会执行到 yield 语句，yield 后面的值作为本次迭代的结果返回，并且函数的状态会被挂起。下次调用 next() 时，函数从上次挂起的地方继续执行。这种方式可以按需生成值，非常节省内存，尤其适合处理大量数据或无限序列。 示例: def count_up_to(n): &quot;&quot;&quot;一个生成从 0 到 n-1 的数字的生成器函数&quot;&quot;&quot; print(&quot;生成器函数开始执行...&quot;) i = 0 while i &lt; n: print(f&quot;即将 yield {i}&quot;) yield i # 产生一个值并暂停 print(f&quot;从 yield {i} 处恢复&quot;) i += 1 print(&quot;生成器函数执行完毕.&quot;) # 调用生成器函数，得到生成器对象 counter_gen = count_up_to(3) print(f&quot;获取生成器对象: {counter_gen}&quot;) # 使用 for 循环迭代生成器 (最常用) print(&quot;
--- 使用 for 循环迭代 ---&quot;) for number in counter_gen: print(f&quot;For 循环接收到: {number}&quot;) # 手动迭代生成器 (演示内部机制) print(&quot;
--- 手动调用 next() ---&quot;) counter_gen_manual = count_up_to(2) try: print(&quot;第一次调用 next()&quot;) val1 = next(counter_gen_manual) print(f&quot;收到值: {val1}&quot;) print(&quot;
第二次调用 next()&quot;) val2 = next(counter_gen_manual) print(f&quot;收到值: {val2}&quot;) print(&quot;
第三次调用 next() (将触发 StopIteration)&quot;) val3 = next(counter_gen_manual) except StopIteration: print(&quot;捕获到 StopIteration，迭代结束&quot;) # 输出示例 (部分): # 获取生成器对象: &lt;generator object count_up_to at 0x...&gt; # --- 使用 for 循环迭代 --- # 生成器函数开始执行... # 即将 yield 0 # For 循环接收到: 0 # 从 yield 0 处恢复 # 即将 yield 1 # For 循环接收到: 1 # 从 yield 1 处恢复 # 即将 yield 2 # For 循环接收到: 2 # 从 yield 2 处恢复 # 生成器函数执行完毕. # # --- 手动调用 next() --- # 第一次调用 next() # 生成器函数开始执行... # 即将 yield 0 # 收到值: 0 # # 第二次调用 next() # 从 yield 0 处恢复 # 即将 yield 1 # 收到值: 1 # # 第三次调用 next() (将触发 StopIteration) # 从 yield 1 处恢复 # 生成器函数执行完毕. # 捕获到 StopIteration，迭代结束   函数注解​  说明: 与变量类型注解类似，函数注解允许为函数的参数和返回值添加类型信息。语法是在参数名后加冒号 : 和类型，在函数定义括号后加箭头 -&gt; 和返回类型。同样，这些注解主要用于文档和静态分析，Python 运行时不强制检查。 示例: # 使用注解定义函数 def send_email(to_address: str, subject: str, body: str, cc_list: list[str] = None) -&gt; bool: &quot;&quot;&quot; 发送邮件函数 (模拟)。 参数: to_address: 收件人邮箱地址。 subject: 邮件主题。 body: 邮件正文。 cc_list: 抄送列表 (可选)。 返回: bool: 表示邮件是否发送成功 (模拟)。 &quot;&quot;&quot; print(f&quot;--- 正在发送邮件 ---&quot;) print(f&quot;收件人: {to_address}&quot;) print(f&quot;主题: {subject}&quot;) print(f&quot;正文: {body[:30]}...&quot;) # 只打印部分正文 if cc_list: print(f&quot;抄送: {', '.join(cc_list)}&quot;) print(&quot;--- 邮件发送 (模拟) 成功 ---&quot;) return True # 获取并打印函数注解信息 print(&quot;函数注解信息:&quot;) print(send_email.__annotations__) # 输出: 函数注解信息: {'to_address': &lt;class 'str'&gt;, 'subject': &lt;class 'str'&gt;, 'body': &lt;class 'str'&gt;, 'cc_list': list[str], 'return': &lt;class 'bool'&gt;} # 调用带注解的函数 success = send_email(&quot;test@example.com&quot;, &quot;会议通知&quot;, &quot;明天上午10点开会。&quot;, [&quot;boss@example.com&quot;]) print(f&quot;邮件发送状态: {success}&quot;)

 import 机制​  说明: Python 使用 import 语句来导入其他 Python 文件（模块）中的代码，以便重用。有几种导入方式： import module_name: 导入整个模块，使用时需要 module_name.function() 或 module_name.variable。import module_name as alias: 导入整个模块，并给它一个别名，使用时 alias.function()。from module_name import name1, name2: 从模块中只导入指定的变量、函数或类，可以直接使用 name1、name2。from module_name import name as alias: 从模块中导入指定名称，并给它一个别名。from module_name import *: 导入模块中所有不以下划线 _ 开头的名称。（不推荐使用，容易造成命名空间污染和混淆） 示例: # 创建一个示例模块文件 my_module.py (假设内容如下): # PI = 3.14159 # def greet(name): # return f&quot;Hello from my_module, {name}!&quot; # class MyClass: # def __init__(self): # print(&quot;MyClass instance created in my_module&quot;) # 在另一个文件中使用 import print(&quot;--- import math ---&quot;) import math # 导入标准库 math 模块 print(f&quot;圆周率 pi: {math.pi}&quot;) # 使用 math.pi print(f&quot;2 的平方根: {math.sqrt(2)}&quot;) # 使用 math.sqrt() print(&quot;
--- import math as m ---&quot;) import math as m # 使用别名 m print(f&quot;自然对数 e: {m.e}&quot;) # 假设 my_module.py 在同一目录下或 Python 搜索路径中 try: print(&quot;
--- from my_module import greet, PI ---&quot;) from my_module import greet, PI # 导入特定名称 print(f&quot;模块中的 PI: {PI}&quot;) # 直接使用 PI message = greet(&quot;World&quot;) # 直接使用 greet print(message) print(&quot;
--- from my_module import MyClass as MC ---&quot;) from my_module import MyClass as MC # 导入并使用别名 obj = MC() # 直接使用别名 MC # 不推荐的方式: from my_module import * # from my_module import * # print(PI) # print(greet(&quot;Again&quot;)) # obj2 = MyClass() except ImportError: print(&quot;
错误：找不到 my_module 模块。请确保 my_module.py 文件存在且在 Python 搜索路径中。&quot;) # 为了让示例能运行，这里简单处理 PI = 3.14 def greet(name): return f&quot;Mock greet: {name}&quot; class MC: pass print(f&quot;模块中的 PI (模拟): {PI}&quot;) message = greet(&quot;World&quot;) print(message) obj = MC() print(&quot;模拟 MyClass 实例创建&quot;)   模块搜索路径​  说明: 当使用 import 时，Python 解释器会按照特定的顺序搜索模块文件： 当前执行脚本所在的目录。环境变量 PYTHONPATH 中指定的目录列表。Python 安装时配置的与平台相关的默认路径（如标准库目录）。 可以通过 sys.path 列表查看当前的搜索路径。 示例: import sys print(&quot;Python 模块搜索路径 (sys.path):&quot;) for i, path in enumerate(sys.path): print(f&quot; {i}: {path}&quot;) # 你可以动态地向 sys.path 添加路径 (通常不推荐，除非必要) # import os # custom_path = '/path/to/your/modules' # if custom_path not in sys.path: # sys.path.append(custom_path) # print(&quot;
添加自定义路径后的 sys.path:&quot;) # print(sys.path)   name属性​  说明: 每个 Python 模块都有一个特殊的内置属性 __name__。当一个模块被直接运行时（作为主程序），它的 __name__ 属性值是字符串 '__main__'。当一个模块被其他模块导入时，它的 __name__ 属性值是该模块的文件名（不含 .py 后缀）。这个特性常用于编写可以在命令行直接运行，也可以被其他模块导入使用的模块。常用 if __name__ == &quot;__main__&quot;: 结构来包含只在直接运行时才执行的代码（如测试代码、主程序逻辑）。 示例: # 假设下面的代码保存在名为 my_script.py 的文件中 def helper_function(): print(&quot;这是一个辅助函数。&quot;) print(f&quot;模块 my_script.py 被加载，__name__ 的值是: {__name__}&quot;) # 这段代码只在 my_script.py 被直接运行时执行 if __name__ == &quot;__main__&quot;: print(&quot;
my_script.py 作为主程序运行。&quot;) helper_function() print(&quot;主程序逻辑执行完毕。&quot;) else: # 这段代码在 my_script.py 被导入时执行 (除了上面的 print __name__) print(&quot;
my_script.py 被导入到其他模块中。&quot;) # --- 如何测试 --- # 1. 直接运行: python my_script.py # 输出会包含: # 模块 my_script.py 被加载，__name__ 的值是: __main__ # my_script.py 作为主程序运行。 # 这是一个辅助函数。 # 主程序逻辑执行完毕。 # # 2. 创建另一个文件 (e.g., main_program.py) 并导入: # # main_program.py # import my_script # print(&quot;
在 main_program.py 中使用 my_script:&quot;) # my_script.helper_function() # # 运行: python main_program.py # 输出会包含: # 模块 my_script.py 被加载，__name__ 的值是: my_script # my_script.py 被导入到其他模块中。 # # 在 main_program.py 中使用 my_script: # 这是一个辅助函数。   包结构(init.py)​  说明: 包 (Package) 是组织 Python 模块的一种方式，它使用“点分模块名”（dotted module names）。一个目录只要包含一个 __init__.py 文件（可以为空），就会被 Python 视为一个包。__init__.py 文件用于标记目录为包，并且可以在其中执行包的初始化代码，或者定义 __all__ 变量来控制 from package import * 时导入哪些模块。 示例: 假设有如下目录结构: my_package/ ├── __init__.py ├── module1.py └── sub_package/ ├── __init__.py └── module2.py # my_package/__init__.py (可以为空，或者): print(&quot;正在初始化 my_package 包...&quot;) # 定义 __all__ 控制 from my_package import * 的行为 __all__ = ['module1', 'some_variable'] # 假设包内有 some_variable some_variable = &quot;Value from my_package&quot; # my_package/module1.py: def func1(): print(&quot;这是 my_package.module1 中的 func1&quot;) # my_package/sub_package/__init__.py (可以为空) # my_package/sub_package/module2.py: def func2(): print(&quot;这是 my_package.sub_package.module2 中的 func2&quot;) # 在其他地方使用这个包: # import my_package.module1 # my_package.module1.func1() # # from my_package import module1 # module1.func1() # # from my_package.sub_package import module2 # module2.func2() # # # 如果 __init__.py 中定义了 __all__ # from my_package import * # module1.func1() # 可以访问 module1 (如果在 __all__ 中) # print(some_variable) # 可以访问 some_variable (如果在 __all__ 中) # # sub_package 不会被导入，除非在 __init__.py 中显式导入或添加到 __all__ (以上为结构和代码示例说明，无法直接运行，需按结构创建文件)  相对导入​  说明: 在同一个包内部，模块之间可以使用相对导入来相互引用，避免硬编码包的绝对路径。相对导入使用点 . 来表示相对位置： from . import module: 从当前目录导入 module。from .module import name: 从当前目录的 module 导入 name。from .. import module: 从上级目录导入 module。from ..subpackage import module: 从上级目录的 subpackage 子包导入 module。 相对导入只能在包内部使用（即，不能在顶级脚本中使用）。 示例: 继续使用上面的包结构: my_package/ # 在 my_package/module1.py 中想要导入同级子包的 module2: # from .sub_package import module2 # 正确的相对导入 # # def func1_uses_func2(): # print(&quot;In func1, calling func2...&quot;) # module2.func2() # 在 my_package/sub_package/module2.py 中想要导入上级包的 module1: # from .. import module1 # 正确的相对导入 # # def func2_uses_func1(): # print(&quot;In func2, calling func1...&quot;) # module1.func1() # --- 注意 --- # 如果你直接运行 module1.py (python my_package/module1.py), # 使用相对导入会报错 (ImportError: attempted relative import with no known parent package) # 因为此时 Python 不认为它是在一个包的上下文中运行。 # 相对导入应该在通过包的入口点运行时才能正常工作, 例如: # # 在 my_package 同级的目录运行一个 main.py: # import my_package.module1 # my_package.module1.func1_uses_func2() (以上为代码示例说明，需结合包结构理解)  常用标准库模块​  说明: Python 自带一个庞大而功能丰富的标准库，提供了许多现成的模块，用于处理各种常见任务。熟悉并善用标准库是高效 Python 开发的关键。 示例 (列举几个常用模块及其简单用法): # os 模块: 与操作系统交互，如文件路径、目录操作等 import os print(f&quot;当前工作目录: {os.getcwd()}&quot;) # print(f&quot;环境变量 PATH: {os.getenv('PATH')}&quot;) # 获取环境变量 # sys 模块: 与 Python 解释器交互，如命令行参数、退出程序、模块路径等 import sys print(f&quot;Python 版本: {sys.version}&quot;) print(f&quot;命令行参数: {sys.argv}&quot;) # sys.exit(0) # 正常退出程序 # math 模块: 数学运算函数 import math print(f&quot;根号 16: {math.sqrt(16)}&quot;) print(f&quot;向上取整 3.14: {math.ceil(3.14)}&quot;) print(f&quot;向下取整 3.14: {math.floor(3.14)}&quot;) # random 模块: 生成随机数 import random print(f&quot;0到1之间的随机浮点数: {random.random()}&quot;) print(f&quot;1到10之间的随机整数: {random.randint(1, 10)}&quot;) my_list = ['a', 'b', 'c', 'd'] random.shuffle(my_list) # 原地打乱列表 print(f&quot;打乱后的列表: {my_list}&quot;) print(f&quot;从列表中随机选择一个元素: {random.choice(my_list)}&quot;) # datetime 模块: 处理日期和时间 import datetime now = datetime.datetime.now() print(f&quot;当前日期和时间: {now}&quot;) print(f&quot;格式化时间: {now.strftime('%Y-%m-%d %H:%M:%S')}&quot;) one_day = datetime.timedelta(days=1) yesterday = now - one_day print(f&quot;昨天: {yesterday}&quot;) # json 模块: 处理 JSON 数据 (序列化和反序列化) import json data = {'name': 'Alice', 'age': 30, 'city': 'New York', 'isStudent': False} json_string = json.dumps(data, indent=4, ensure_ascii=False) # 序列化为 JSON 字符串 print(f&quot;
JSON 字符串:
{json_string}&quot;) parsed_data = json.loads(json_string) # 反序列化回 Python 字典 print(f&quot;解析后的数据 (字典): {parsed_data}&quot;) # re 模块: 正则表达式操作 import re text = &quot;我的电话号码是 138-1234-5678，另一个是 159-8765-4321。&quot; # 查找所有符合模式的电话号码 phone_numbers = re.findall(r'\d{3}-\d{4}-\d{4}', text) print(f&quot;
找到的电话号码: {phone_numbers}&quot;) # 输出: 找到的电话号码: ['138-1234-5678', '159-8765-4321']

 集合(set)及操作​  说明: 集合是一个无序的、不重复的元素集合。主要用于成员测试（检查元素是否存在）和消除重复元素。集合中的元素必须是不可变类型（如 int, float, str, tuple）。使用花括号 {} 或 set() 函数创建。注意，创建空集合必须用 set()，因为 {} 创建的是空字典。 常用操作: 添加元素: add(item)删除元素: remove(item) (若不存在则报错 KeyError), discard(item) (若不存在则不报错), pop() (随机删除并返回一个元素)清空集合: clear()成员测试: in, not in (非常高效)集合运算: 并集 (Union): set1 | set2 或 set1.union(set2)交集 (Intersection): set1 &amp; set2 或 set1.intersection(set2)差集 (Difference): set1 - set2 或 set1.difference(set2) (返回在 set1 但不在 set2 中的元素)对称差集 (Symmetric Difference): set1 ^ set2 或 set1.symmetric_difference(set2) (返回只在其中一个集合中出现的元素) 子集与超集判断: issubset(), issuperset() 示例: # 创建集合 set1 = {1, 2, 3, 3, 4} # 重复的 3 会被自动忽略 set2 = set([3, 4, 5, 6]) empty_set = set() print(f&quot;set1: {set1}&quot;) # 输出: {1, 2, 3, 4} (顺序可能不同) print(f&quot;set2: {set2}&quot;) # 输出: {3, 4, 5, 6} print(f&quot;空集合: {empty_set}&quot;) # 输出: set() # 添加元素 set1.add(5) print(f&quot;add(5) 后 set1: {set1}&quot;) # {1, 2, 3, 4, 5} # 删除元素 set1.remove(2) # 删除 2 print(f&quot;remove(2) 后 set1: {set1}&quot;) # {1, 3, 4, 5} set1.discard(10) # 尝试删除不存在的 10，不会报错 print(f&quot;discard(10) 后 set1: {set1}&quot;) # {1, 3, 4, 5} item = set1.pop() # 随机移除一个元素 print(f&quot;pop() 移除的元素: {item}, set1 变为: {set1}&quot;) # 成员测试 print(f&quot;4 in set2? {4 in set2}&quot;) # True print(f&quot;10 not in set2? {10 not in set2}&quot;) # True # 集合运算 s_a = {1, 2, 3, 4} s_b = {3, 4, 5, 6} print(f&quot;
集合 A: {s_a}&quot;) print(f&quot;集合 B: {s_b}&quot;) print(f&quot;并集 (A | B): {s_a | s_b}&quot;) # {1, 2, 3, 4, 5, 6} print(f&quot;交集 (A &amp; B): {s_a &amp; s_b}&quot;) # {3, 4} print(f&quot;差集 (A - B): {s_a - s_b}&quot;) # {1, 2} print(f&quot;差集 (B - A): {s_b - s_a}&quot;) # {5, 6} print(f&quot;对称差集 (A ^ B): {s_a ^ s_b}&quot;) # {1, 2, 5, 6} # 子集与超集 s_c = {1, 2} print(f&quot;{s_c} 是 {s_a} 的子集吗? {s_c.issubset(s_a)}&quot;) # True print(f&quot;{s_a} 是 {s_c} 的超集吗? {s_a.issuperset(s_c)}&quot;) # True print(f&quot;{s_a} 是 {s_b} 的子集吗? {s_a.issubset(s_b)}&quot;) # False # 集合用于去重 my_list = [1, 2, 2, 3, 1, 4, 5, 4] unique_elements = set(my_list) print(f&quot;
列表去重后的集合: {unique_elements}&quot;) # {1, 2, 3, 4, 5} unique_list = list(unique_elements) print(f&quot;转换回列表: {unique_list}&quot;) # [1, 2, 3, 4, 5] (顺序不保证)   不可变集合(frozenset)​  说明: frozenset 是集合的不可变版本。一旦创建，不能添加或删除元素。由于其不可变性，frozenset 可以作为字典的键或集合中的元素。它支持所有非修改性的集合操作（如并集、交集、差集、成员测试等）。 示例: # 创建 frozenset fs1 = frozenset([1, 2, 3, 3]) fs2 = frozenset({3, 4, 5}) print(f&quot;fs1: {fs1}&quot;) # frozenset({1, 2, 3}) print(f&quot;fs2: {fs2}&quot;) # frozenset({3, 4, 5}) # frozenset 是不可变的 # fs1.add(4) # AttributeError: 'frozenset' object has no attribute 'add' # fs1.remove(1) # AttributeError: 'frozenset' object has no attribute 'remove' # 支持非修改性操作 print(f&quot;并集: {fs1.union(fs2)}&quot;) # frozenset({1, 2, 3, 4, 5}) print(f&quot;交集: {fs1.intersection(fs2)}&quot;) # frozenset({3}) print(f&quot;差集 (fs1 - fs2): {fs1.difference(fs2)}&quot;) # frozenset({1, 2}) print(f&quot;3 in fs1? {3 in fs1}&quot;) # True # 可以作为字典的键 set_map = {fs1: &quot;Set One&quot;, fs2: &quot;Set Two&quot;} print(f&quot;字典中的键值对: {set_map}&quot;) print(f&quot;查找 fs1 对应的值: {set_map[fs1]}&quot;) # Set One # 可以作为集合的元素 set_of_frozensets = {fs1, fs2, frozenset([1, 2])} print(f&quot;包含 frozenset 的集合: {set_of_frozensets}&quot;)   字典(dict)及常用方法​  说明: 字典是 Python 中的核心映射类型。它存储键值对 (key-value pairs) 的集合。键必须是唯一的且不可变类型（如 int, float, str, tuple, frozenset），值可以是任意类型。字典是无序的（在 Python 3.7+ 中，字典会保持插入顺序，但这被认为是实现细节，不应过分依赖），通过键来快速查找、添加、修改、删除对应的值。使用花括号 {} 创建，键值对格式为 key: value，用逗号 , 分隔。 常用方法: 访问/修改: d[key] (若 key 不存在则报错 KeyError), d.get(key[, default]) (若 key 不存在则返回 default，默认 None)添加/更新: d[key] = value, d.update(other_dict) (用 other_dict 更新 d)删除: del d[key] (若 key 不存在则报错 KeyError), d.pop(key[, default]) (删除并返回 key 对应的值，若 key 不存在且未提供 default 则报错), d.popitem() (删除并返回一个任意或最后一个（3.7+）键值对), d.clear() (清空字典)获取视图: d.keys(), d.values(), d.items() (返回动态视图对象，可迭代)成员测试: key in d (检查键是否存在，高效) 示例: # 创建字典 student = { &quot;name&quot;: &quot;张三&quot;, &quot;age&quot;: 20, &quot;major&quot;: &quot;计算机科学&quot;, &quot;grades&quot;: {&quot;math&quot;: 90, &quot;english&quot;: 85} } empty_dict = {} dict_from_tuples = dict([('a', 1), ('b', 2)]) print(f&quot;学生字典: {student}&quot;) print(f&quot;空字典: {empty_dict}&quot;) print(f&quot;从元组列表创建: {dict_from_tuples}&quot;) # {'a': 1, 'b': 2} # 访问值 print(f&quot;姓名: {student['name']}&quot;) # 张三 print(f&quot;年龄 (get): {student.get('age')}&quot;) # 20 print(f&quot;地址 (get, 带默认值): {student.get('address', '未知')}&quot;) # 未知 # print(student['address']) # 会报错 KeyError # 修改值 student['age'] = 21 print(f&quot;修改年龄后: {student}&quot;) # 添加键值对 student['city'] = &quot;北京&quot; print(f&quot;添加城市后: {student}&quot;) # 使用 update 更新或添加多个键值对 student.update({&quot;major&quot;: &quot;软件工程&quot;, &quot;phone&quot;: &quot;138xxxx&quot;}) print(f&quot;update 后: {student}&quot;) # 删除键值对 del student['grades'] # 删除 grades print(f&quot;删除 grades 后: {student}&quot;) phone = student.pop('phone') # 删除并返回 phone 的值 print(f&quot;pop('phone') 返回: {phone}, 字典变为: {student}&quot;) key_value = student.popitem() # 删除并返回最后一项 (Python 3.7+) print(f&quot;popitem() 返回: {key_value}, 字典变为: {student}&quot;) # 检查键是否存在 print(f&quot;'name' in student? {'name' in student}&quot;) # True print(f&quot;'grades' in student? {'grades' in student}&quot;) # False # 字典视图 (keys, values, items) print(&quot;
--- 字典视图 ---&quot;) print(f&quot;所有键 (Keys): {student.keys()}&quot;) # dict_keys(['name', 'age', 'major']) print(f&quot;所有值 (Values): {student.values()}&quot;) # dict_values(['张三', 21, '软件工程']) print(f&quot;所有项 (Items): {student.items()}&quot;) # dict_items([('name', '张三'), ('age', 21), ('major', '软件工程')]) # 遍历字典 print(&quot;
--- 遍历字典 ---&quot;) print(&quot;遍历键:&quot;) for key in student: # 默认遍历键 print(f&quot; {key}&quot;) print(&quot;
遍历值:&quot;) for value in student.values(): print(f&quot; {value}&quot;) print(&quot;
遍历键值对:&quot;) for key, value in student.items(): print(f&quot; {key}: {value}&quot;) # 清空字典 student.clear() print(f&quot;
清空后字典: {student}&quot;) # {}   字典视图(keys(), values(), items())​  说明: 字典的 keys(), values(), items() 方法返回的是特殊的“视图”对象，而不是列表。视图对象提供字典内容的动态窗口，意味着如果字典发生变化，视图会实时反映这些变化。它们都是可迭代的。 keys(): 返回包含字典所有键的视图。values(): 返回包含字典所有值的视图。items(): 返回包含字典所有 (键, 值) 元组的视图。 示例: my_dict = {'a': 1, 'b': 2, 'c': 3} keys_view = my_dict.keys() values_view = my_dict.values() items_view = my_dict.items() print(f&quot;原始字典: {my_dict}&quot;) print(f&quot;Keys 视图: {keys_view}&quot;) # dict_keys(['a', 'b', 'c']) print(f&quot;Values 视图: {values_view}&quot;) # dict_values([1, 2, 3]) print(f&quot;Items 视图: {items_view}&quot;) # dict_items([('a', 1), ('b', 2), ('c', 3)]) # 视图是动态的 print(&quot;
--- 修改字典后观察视图变化 ---&quot;) my_dict['d'] = 4 # 添加新项 del my_dict['a'] # 删除一项 print(f&quot;修改后字典: {my_dict}&quot;) print(f&quot;Keys 视图 (已更新): {keys_view}&quot;) # dict_keys(['b', 'c', 'd']) print(f&quot;Values 视图 (已更新): {values_view}&quot;) # dict_values([2, 3, 4]) print(f&quot;Items 视图 (已更新): {items_view}&quot;) # dict_items([('b', 2), ('c', 3), ('d', 4)]) # 视图是可迭代的 print(&quot;
--- 迭代视图 ---&quot;) print(&quot;迭代 Keys:&quot;) for key in keys_view: print(f&quot; {key}&quot;) print(&quot;迭代 Values:&quot;) for value in values_view: print(f&quot; {value}&quot;) print(&quot;迭代 Items:&quot;) for key, value in items_view: print(f&quot; {key} -&gt; {value}&quot;) # 可以将视图转换为列表 (创建快照) key_list = list(keys_view) value_list = list(values_view) item_list = list(items_view) print(f&quot;
视图转为列表 (快照):&quot;) print(f&quot; 键列表: {key_list}&quot;) print(f&quot; 值列表: {value_list}&quot;) print(f&quot; 项列表: {item_list}&quot;) # 视图支持成员测试 print(f&quot;'b' in keys_view? {'b' in keys_view}&quot;) # True # print(f&quot;1 in values_view? {1 in values_view}&quot;) # False (因为 'a': 1 被删了) print(f&quot;3 in values_view? {3 in values_view}&quot;) # True print(f&quot;('c', 3) in items_view? {('c', 3) in items_view}&quot;) # True

 collections 模块(namedtuple, deque, Counter 等)​  说明: collections 模块提供了标准内置容器（dict, list, set, tuple）的替代品，以及一些专门的数据结构。 namedtuple: 创建类似元组的对象，但可以通过名称和索引访问字段。更具可读性。deque (双端队列): 类似列表，但在两端添加和删除元素的操作非常高效（时间复杂度 O(1)）。适用于实现队列和栈。Counter: dict 的子类，用于计算可哈希对象的频率。键是元素，值是计数。OrderedDict: （在 Python 3.7+ 中 dict 已保持插入顺序，OrderedDict 重要性下降，但仍提供一些额外功能，如 move_to_end 和保证顺序比较）一个记住元素添加顺序的字典。defaultdict: dict 的子类，在访问不存在的键时，会自动调用一个工厂函数（如 int, list, set）来生成默认值，避免了 KeyError。 示例: import collections # --- namedtuple --- print(&quot;--- collections.namedtuple ---&quot;) # 定义一个名为 Point 的 namedtuple，包含 x 和 y 两个字段 Point = collections.namedtuple('Point', ['x', 'y']) p1 = Point(10, 20) p2 = Point(x=5, y=15) print(f&quot;点 p1: {p1}&quot;) # Point(x=10, y=20) print(f&quot;p1 的 x 坐标 (按名称): {p1.x}&quot;) # 10 print(f&quot;p1 的 y 坐标 (按索引): {p1[1]}&quot;) # 20 print(f&quot;点 p2: {p2}&quot;) # Point(x=5, y=15) # --- deque --- print(&quot;
--- collections.deque ---&quot;) d = collections.deque(['a', 'b', 'c']) print(f&quot;初始 deque: {d}&quot;) # deque(['a', 'b', 'c']) # 右端添加 d.append('d') print(f&quot;append('d') 后: {d}&quot;) # deque(['a', 'b', 'c', 'd']) # 左端添加 d.appendleft('z') print(f&quot;appendleft('z') 后: {d}&quot;) # deque(['z', 'a', 'b', 'c', 'd']) # 右端弹出 item_right = d.pop() print(f&quot;pop() 返回: {item_right}, deque 变为: {d}&quot;) # d, deque(['z', 'a', 'b', 'c']) # 左端弹出 item_left = d.popleft() print(f&quot;popleft() 返回: {item_left}, deque 变为: {d}&quot;) # z, deque(['a', 'b', 'c']) # 旋转 d.rotate(1) # 右旋 1 位 print(f&quot;rotate(1) 后: {d}&quot;) # deque(['c', 'a', 'b']) d.rotate(-1) # 左旋 1 位 print(f&quot;rotate(-1) 后: {d}&quot;) # deque(['a', 'b', 'c']) # --- Counter --- print(&quot;
--- collections.Counter ---&quot;) sentence = &quot;this is a sample sentence with several sample words&quot; words = sentence.split() word_counts = collections.Counter(words) print(f&quot;单词计数: {word_counts}&quot;) # Counter({'sample': 2, 'this': 1, 'is': 1, 'a': 1, 'sentence': 1, 'with': 1, 'several': 1, 'words': 1}) print(f&quot;'sample' 出现的次数: {word_counts['sample']}&quot;) # 2 print(f&quot;出现次数最多的 2 个单词: {word_counts.most_common(2)}&quot;) # [('sample', 2), ('this', 1)] (或其它次数为1的词) # Counter 支持算术运算 c1 = collections.Counter('aabbc') # Counter({'a': 2, 'b': 2, 'c': 1}) c2 = collections.Counter('abbd') # Counter({'b': 2, 'a': 1, 'd': 1}) print(f&quot;c1 + c2 (合并计数): {c1 + c2}&quot;) # Counter({'b': 4, 'a': 3, 'c': 1, 'd': 1}) print(f&quot;c1 - c2 (只保留正计数): {c1 - c2}&quot;) # Counter({'a': 1, 'c': 1}) # --- defaultdict --- print(&quot;
--- collections.defaultdict ---&quot;) # 创建一个默认值为 int (即 0) 的 defaultdict dd_int = collections.defaultdict(int) dd_int['a'] += 1 print(f&quot;dd_int['a']: {dd_int['a']}&quot;) # 1 (访问不存在的 'a' 时自动创建为 0) print(f&quot;dd_int['b']: {dd_int['b']}&quot;) # 0 (访问不存在的 'b' 时自动创建为 0) print(f&quot;dd_int: {dd_int}&quot;) # defaultdict(&lt;class 'int'&gt;, {'a': 1, 'b': 0}) # 创建一个默认值为 list 的 defaultdict dd_list = collections.defaultdict(list) dd_list['fruits'].append('apple') dd_list['fruits'].append('banana') dd_list['vegetables'].append('carrot') print(f&quot;dd_list: {dd_list}&quot;) # defaultdict(&lt;class 'list'&gt;, {'fruits': ['apple', 'banana'], 'vegetables': ['carrot']}) # --- OrderedDict (了解即可, Python 3.7+ dict 默认保持顺序) --- # print(&quot;
--- collections.OrderedDict ---&quot;) # od = collections.OrderedDict() # od['b'] = 2 # od['a'] = 1 # od['c'] = 3 # print(f&quot;OrderedDict: {od}&quot;) # OrderedDict([('b', 2), ('a', 1), ('c', 3)]) # for key, value in od.items(): # print(f&quot; {key}: {value}&quot;) # 保证按插入顺序 ('b', 'a', 'c') 输出   array 数组​  说明: array 模块提供了一个 array 类型，它类似于列表，但要求所有元素必须是相同且指定的 C 语言数值类型（如 int, float）。这使得 array 在存储大量数值数据时比列表更节省内存，并且在某些底层操作（如直接写入文件或通过 C 扩展处理）时可能更高效。类型通过一个“类型码”（type code）在创建时指定。 常用类型码: 'b' (signed char), 'B' (unsigned char), 'h' (signed short), 'H' (unsigned short), 'i' (signed int), 'I' (unsigned int), 'l' (signed long), 'L' (unsigned long), 'f' (float), 'd' (double). 示例: import array # 创建一个存储有符号整数 ('i') 的 array int_array = array.array('i', [10, -20, 30, 0, 50]) print(f&quot;整数数组: {int_array}&quot;) # array('i', [10, -20, 30, 0, 50]) print(f&quot;类型码: {int_array.typecode}&quot;) # i print(f&quot;每个元素字节数: {int_array.itemsize}&quot;) # 通常是 4 # 创建一个存储双精度浮点数 ('d') 的 array float_array = array.array('d', [1.1, 2.2, 3.3]) print(f&quot;
浮点数数组: {float_array}&quot;) # array('d', [1.1, 2.2, 3.3]) print(f&quot;类型码: {float_array.typecode}&quot;) # d print(f&quot;每个元素字节数: {float_array.itemsize}&quot;) # 通常是 8 # array 支持类似列表的操作 int_array.append(60) print(f&quot;append(60) 后: {int_array}&quot;) # array('i', [..., 50, 60]) print(f&quot;第一个元素: {int_array[0]}&quot;) # 10 int_array[0] = 100 # 修改元素 print(f&quot;修改第一个元素后: {int_array}&quot;) # array('i', [100, -20, ...]) # 尝试添加不同类型会报错 TypeError # int_array.append(1.5) # TypeError: integer argument expected, got float # array 可以方便地与文件或字节数据互操作 # 写入文件 try: with open('my_array.bin', 'wb') as f: int_array.tofile(f) print(&quot;
数组已写入到 my_array.bin&quot;) # 从文件读取 read_array = array.array('i') # 创建空的同类型 array with open('my_array.bin', 'rb') as f: # 需要知道要读取多少个元素，或者读取到文件末尾 # 这里假设我们知道原始大小 file_size = os.path.getsize('my_array.bin') num_items = file_size // read_array.itemsize read_array.fromfile(f, num_items) print(f&quot;从文件读取的数组: {read_array}&quot;) except Exception as e: print(f&quot;
文件操作出错: {e}&quot;) # 捕获可能的错误，如文件权限 # 与 bytes 转换 byte_data = int_array.tobytes() print(f&quot;
数组转为 bytes: {byte_data[:20]}...&quot;) # 显示前 20 字节 new_array = array.array('i') new_array.frombytes(byte_data) print(f&quot;从 bytes 恢复的数组: {new_array}&quot;)   heapq 堆队列​  说明: heapq 模块提供了堆队列算法（Heap Queue Algorithm），也称为优先队列算法（Priority Queue Algorithm）的实现。堆是一个特殊的树状数据结构，其特性是父节点的值总是小于或等于（最小堆，heapq 默认实现）或大于或等于（最大堆）其子节点的值。heapq 使用普通的 Python 列表来表示堆。它提供了高效地添加元素 (heappush) 和弹出最小元素 (heappop) 的操作（时间复杂度 O(log n)）。 常用函数: heapq.heappush(heap, item): 将 item 推入堆 heap，保持堆特性。heapq.heappop(heap): 从堆 heap 中弹出并返回最小的项，保持堆特性。如果堆为空，则引发 IndexError。heapq.heapify(x): 将列表 x 原地转换为堆。时间复杂度 O(n)。heapq.heappushpop(heap, item): 将 item 推入堆，然后弹出并返回最小项。比 heappush 后 heappop 更高效。heapq.heapreplace(heap, item): 弹出并返回最小项，然后将 item 推入堆。比 heappop 后 heappush 更高效（堆不为空时）。heapq.nsmallest(n, iterable[, key]): 返回 iterable 中 n 个最小的元素列表。heapq.nlargest(n, iterable[, key]): 返回 iterable 中 n 个最大的元素列表。 示例: import heapq # 使用 heapq 实现优先队列 (最小堆) min_heap = [] # 使用普通列表 # 推入元素 heapq.heappush(min_heap, 5) heapq.heappush(min_heap, 1) heapq.heappush(min_heap, 8) heapq.heappush(min_heap, 3) print(f&quot;最小堆 (内部列表表示): {min_heap}&quot;) # 内部顺序不一定是完全排序的，但满足堆特性 [1, 3, 8, 5] # 弹出最小元素 smallest = heapq.heappop(min_heap) print(f&quot;弹出的最小元素: {smallest}&quot;) # 1 print(f&quot;弹出后堆: {min_heap}&quot;) # [3, 5, 8] smallest = heapq.heappop(min_heap) print(f&quot;弹出的最小元素: {smallest}&quot;) # 3 print(f&quot;弹出后堆: {min_heap}&quot;) # [5, 8] # heapify: 将列表原地转为堆 data = [9, 2, 7, 4, 6, 1, 8, 5, 3] heapq.heapify(data) print(f&quot;
heapify 后的列表 (堆): {data}&quot;) # [1, 2, 3, 4, 6, 7, 8, 5, 9] # nsmallest 和 nlargest nums = [10, 4, 25, 8, 15, 6, 30] print(f&quot;
列表: {nums}&quot;) print(f&quot;最小的 3 个元素: {heapq.nsmallest(3, nums)}&quot;) # [4, 6, 8] print(f&quot;最大的 2 个元素: {heapq.nlargest(2, nums)}&quot;) # [30, 25] # 获取带优先级的元素 (元组的第一项作为优先级) priority_queue = [] heapq.heappush(priority_queue, (5, '任务A')) # 优先级 5 heapq.heappush(priority_queue, (1, '任务B')) # 优先级 1 (最高) heapq.heappush(priority_queue, (3, '任务C')) # 优先级 3 print(f&quot;
优先队列: {priority_queue}&quot;) # [(1, '任务B'), (5, '任务A'), (3, '任务C')] while priority_queue: priority, task = heapq.heappop(priority_queue) print(f&quot;处理任务: {task} (优先级: {priority})&quot;) # 输出: # 处理任务: 任务B (优先级: 1) # 处理任务: 任务C (优先级: 3) # 处理任务: 任务A (优先级: 5)   bisect 二分查找​  说明: bisect 模块提供了在已排序的列表中进行二分查找和插入的功能。这对于维护一个有序列表非常有用。 常用函数: bisect.bisect_left(a, x[, lo=0[, hi=len(a)]]): 在已排序列表 a 中查找 x 的插入点，返回索引 i。如果 x 已存在，则返回现有元素左边的索引。所有 a[:i] 中的元素都 &lt; x，所有 a[i:] 中的元素都 &gt;= x。bisect.bisect_right(a, x[, lo=0[, hi=len(a)]]) (或 bisect.bisect(a, x, ...)): 类似 bisect_left，但如果 x 已存在，返回现有元素右边的索引。所有 a[:i] 中的元素都 &lt;= x，所有 a[i:] 中的元素都 &gt; x。bisect.insort_left(a, x[, lo=0[, hi=len(a)]]): 将 x 插入到已排序列表 a 中，并保持排序。如果 x 已存在，插入到现有元素左边。bisect.insort_right(a, x[, lo=0[, hi=len(a)]]) (或 bisect.insort(a, x, ...)): 类似 insort_left，但如果 x 已存在，插入到现有元素右边。 示例: import bisect sorted_list = [10, 20, 30, 30, 40, 50] print(f&quot;已排序列表: {sorted_list}&quot;) # 查找插入点 # 查找 25 的插入点 index_25_left = bisect.bisect_left(sorted_list, 25) index_25_right = bisect.bisect_right(sorted_list, 25) print(f&quot;查找 25: bisect_left 返回索引 {index_25_left}, bisect_right 返回索引 {index_25_right}&quot;) # 2, 2 # 查找已存在元素 30 的插入点 index_30_left = bisect.bisect_left(sorted_list, 30) index_30_right = bisect.bisect_right(sorted_list, 30) print(f&quot;查找 30: bisect_left 返回索引 {index_30_left}, bisect_right 返回索引 {index_30_right}&quot;) # 2, 4 # 查找小于 10 的值 (0) index_0_left = bisect.bisect_left(sorted_list, 0) print(f&quot;查找 0: bisect_left 返回索引 {index_0_left}&quot;) # 0 # 查找大于 50 的值 (60) index_60_right = bisect.bisect_right(sorted_list, 60) print(f&quot;查找 60: bisect_right 返回索引 {index_60_right}&quot;) # 6 (列表长度) # 使用 insort 插入元素并保持排序 print(&quot;
--- 使用 insort 插入元素 ---&quot;) my_sorted_list = [] bisect.insort(my_sorted_list, 30) print(f&quot;插入 30: {my_sorted_list}&quot;) # [30] bisect.insort(my_sorted_list, 10) print(f&quot;插入 10: {my_sorted_list}&quot;) # [10, 30] bisect.insort(my_sorted_list, 20) print(f&quot;插入 20: {my_sorted_list}&quot;) # [10, 20, 30] bisect.insort(my_sorted_list, 30) # 插入重复元素 (默认 insort_right) print(f&quot;插入 30: {my_sorted_list}&quot;) # [10, 20, 30, 30] bisect.insort_left(my_sorted_list, 20) # 使用 insort_left 插入重复元素 print(f&quot;insort_left 插入 20: {my_sorted_list}&quot;) # [10, 20, 20, 30, 30] # 应用：根据分数查找等级 def find_grade(score, breakpoints=[60, 70, 80, 90], grades='FDCBA'): # bisect 返回的索引可以直接用于在 grades 字符串中查找等级 i = bisect.bisect(breakpoints, score) return grades[i] print(&quot;
--- 根据分数查找等级 ---&quot;) print(f&quot;分数 55 的等级: {find_grade(55)}&quot;) # F print(f&quot;分数 60 的等级: {find_grade(60)}&quot;) # D print(f&quot;分数 75 的等级: {find_grade(75)}&quot;) # C print(f&quot;分数 90 的等级: {find_grade(90)}&quot;) # A print(f&quot;分数 95 的等级: {find_grade(95)}&quot;) # A   枚举(enum)​  说明: enum 模块（Python 3.4+）提供了创建枚举类型（Enumerations）的支持。枚举是一组绑定到唯一常量值的符号名称（成员）。使用枚举可以使代码更清晰、更易读，减少因使用魔法数字或字符串而导致的错误。 特性: 枚举成员是唯一的，可以通过名称访问。枚举成员具有值，也可以通过值查找成员。枚举是可迭代的。枚举成员是其所属枚举类的实例。默认情况下，不允许枚举成员具有相同的值（可配置）。 示例: import enum # 定义一个表示颜色的枚举 class Color(enum.Enum): RED = 1 # 成员名称 = 值 GREEN = 2 BLUE = 3 # 也可以自动赋值 (如果不需要关心具体值) # YELLOW = enum.auto() # PURPLE = enum.auto() # 访问枚举成员 print(&quot;--- 访问枚举成员 ---&quot;) print(f&quot;成员 RED: {Color.RED}&quot;) # Color.RED (成员本身) print(f&quot;RED 的名称: {Color.RED.name}&quot;) # RED print(f&quot;RED 的值: {Color.RED.value}&quot;) # 1 # 通过值查找成员 print(f&quot;值为 2 的成员: {Color(2)}&quot;) # Color.GREEN # 比较枚举成员 selected_color = Color.GREEN print(f&quot;选择的颜色是 RED 吗? {selected_color == Color.RED}&quot;) # False print(f&quot;选择的颜色是 GREEN 吗? {selected_color == Color.GREEN}&quot;) # True # 枚举成员与它们的值不相等 print(f&quot;Color.BLUE == 3? {Color.BLUE == 3}&quot;) # False # 迭代枚举 print(&quot;
--- 迭代枚举 ---&quot;) for color in Color: print(f&quot; 成员: {color}, 名称: {color.name}, 值: {color.value}&quot;) # 在函数中使用枚举 def process_color(color: Color): if color == Color.RED: print(&quot;处理红色...&quot;) elif color == Color.GREEN: print(&quot;处理绿色...&quot;) elif color == Color.BLUE: print(&quot;处理蓝色...&quot;) else: print(f&quot;处理未知颜色: {color}&quot;) print(&quot;
--- 在函数中使用枚举 ---&quot;) process_color(Color.BLUE) # 处理蓝色... # process_color(1) # 传递非枚举值 (如果函数有类型注解，静态检查会警告) # 定义一个带有字符串值的枚举 class Status(enum.Enum): PENDING = 'pending' RUNNING = 'running' COMPLETED = 'completed' FAILED = 'failed' print(&quot;
--- 状态枚举 ---&quot;) current_status = Status.RUNNING print(f&quot;当前状态: {current_status}&quot;) # Status.RUNNING print(f&quot;当前状态的值: {current_status.value}&quot;) # running print(f&quot;通过值查找 'failed': {Status('failed')}&quot;) # Status.FAILED

 类定义与实例化​  说明: 类 (Class) 是创建对象的蓝图或模板。它定义了对象的属性（数据）和方法（行为）。使用 class 关键字定义类。实例化 (Instantiation) 是根据类的定义创建具体对象（实例）的过程，通过类名加括号 () 实现。__init__ 是一个特殊的初始化方法（构造函数），在对象创建后自动调用，用于设置对象的初始状态。 示例: class Dog: # __init__ 方法是构造函数，self 代表实例本身 def __init__(self, name, breed): # 实例属性：每个 Dog 对象都有自己的 name 和 breed self.name = name self.breed = breed print(f&quot;一只名叫 {self.name} ({self.breed}) 的狗狗诞生了！&quot;) # 实例方法：对象可以调用的函数 def bark(self): print(f&quot;{self.name}: 汪汪！&quot;) # 实例化：创建 Dog 类的两个对象（实例） dog1 = Dog(&quot;旺财&quot;, &quot;中华田园犬&quot;) dog2 = Dog(&quot;小白&quot;, &quot;萨摩耶&quot;) # 调用实例的方法 dog1.bark() # 输出: 旺财: 汪汪！ dog2.bark() # 输出: 小白: 汪汪！ # 访问实例的属性 print(f&quot;{dog1.name} 的品种是 {dog1.breed}&quot;) # 输出: 旺财 的品种是 中华田园犬   实例属性与类属性​  说明: 实例属性 (Instance Attributes): 每个对象各自独有的属性，通常在 __init__ 方法中使用 self.attribute_name = value 来定义。它们存储对象特定的状态。类属性 (Class Attributes): 定义在类内部、方法外部的属性。它们被该类的所有实例共享。可以通过类名或实例名访问，但通过实例修改类属性（如果属性是不可变类型）实际上是创建了一个同名的实例属性，遮盖了类属性；如果类属性是可变类型，通过实例修改会影响所有其他实例。 示例: class Car: # 类属性：所有 Car 实例共享 wheels = 4 def __init__(self, color, brand): # 实例属性：每个 Car 对象独有 self.color = color self.brand = brand # 创建实例 car1 = Car(&quot;红色&quot;, &quot;特斯拉&quot;) car2 = Car(&quot;蓝色&quot;, &quot;宝马&quot;) # 访问类属性 print(f&quot;通过类访问轮子数: {Car.wheels}&quot;) # 输出: 4 print(f&quot;通过 car1 访问轮子数: {car1.wheels}&quot;) # 输出: 4 print(f&quot;通过 car2 访问轮子数: {car2.wheels}&quot;) # 输出: 4 # 访问实例属性 print(f&quot;car1 的颜色: {car1.color}&quot;) # 输出: 红色 print(f&quot;car2 的品牌: {car2.brand}&quot;) # 输出: 宝马 # 修改类属性 (会影响所有实例) # Car.wheels = 6 # print(f&quot;
修改类属性后，car1 轮子数: {car1.wheels}&quot;) # 输出: 6 # 通过实例修改类属性 (实际上是给 car1 创建了一个实例属性 'wheels') # car1.wheels = 5 # print(f&quot;
通过 car1 修改后:&quot;) # print(f&quot; car1 的 wheels: {car1.wheels}&quot;) # 输出: 5 (实例属性) # print(f&quot; car2 的 wheels: {car2.wheels}&quot;) # 输出: 4 (仍然是类属性) # print(f&quot; Car 的 wheels: {Car.wheels}&quot;) # 输出: 4 (类属性未变)   方法(self 参数)​  说明: 方法 (Method) 是定义在类内部的函数。实例方法是类中最常见的方法类型，它们的第一个参数必须是 self（按照约定俗成的命名，可以是其他名称，但不推荐）。self 参数代表调用该方法的实例对象本身，允许方法访问和修改实例的属性。调用实例方法时，不需要显式传递 self 参数，Python 会自动传入。 示例: class Account: def __init__(self, account_id, balance=0): self.account_id = account_id self.balance = balance # 实例方法：需要 self 参数来访问实例属性 balance def deposit(self, amount): &quot;&quot;&quot;存款&quot;&quot;&quot; if amount &gt; 0: self.balance += amount print(f&quot;账户 {self.account_id} 存入 {amount}, 当前余额: {self.balance}&quot;) else: print(&quot;存款金额必须大于 0&quot;) def withdraw(self, amount): &quot;&quot;&quot;取款&quot;&quot;&quot; if 0 &lt; amount &lt;= self.balance: self.balance -= amount print(f&quot;账户 {self.account_id} 取出 {amount}, 当前余额: {self.balance}&quot;) else: print(&quot;取款金额无效或余额不足&quot;) def get_balance(self): &quot;&quot;&quot;查询余额&quot;&quot;&quot; return self.balance # 创建账户实例 acc1 = Account(&quot;ACC001&quot;, 1000) # 调用实例方法 (不需要传 self) acc1.deposit(500) # 输出: 账户 ACC001 存入 500, 当前余额: 1500 acc1.withdraw(200) # 输出: 账户 ACC001 取出 200, 当前余额: 1300 current_balance = acc1.get_balance() print(f&quot;账户 {acc1.account_id} 的最终余额: {current_balance}&quot;) # 输出: 1300   私有属性与名称改写​  说明: Python 没有严格意义上的私有属性或方法（像 Java 的 private）。但是，有两种约定俗成的表示“私有”的方式： 单下划线前缀 (_): 例如 _spam。这是一种弱“内部使用”指示，告诉其他程序员这个属性或方法是内部实现细节，不应该在类外部直接访问。但 Python 本身不阻止访问。双下划线前缀 (__): 例如 __eggs。这会触发“名称改写 (Name Mangling)”。Python 解释器会自动将名称改为 _ClassName__attributeName 的形式（如 _MyClass__eggs）。这使得在类外部意外访问或在子类中意外覆盖变得更困难，但仍然可以通过改写后的名称访问。 示例: class Secretive: def __init__(self): self.public_data = &quot;这是公开的&quot; self._internal_use = &quot;内部使用的，但不强制&quot; self.__private_stuff = &quot;这是“私有”的&quot; def get_private(self): # 在类内部可以正常访问 __private_stuff return self.__private_stuff def _internal_method(self): print(&quot;这是一个内部方法&quot;) def __private_method(self): print(&quot;这是一个“私有”方法&quot;) def call_private_method(self): self.__private_method() # 内部可以调用 s = Secretive() print(s.public_data) # 输出: 这是公开的 print(s._internal_use) # 输出: 内部使用的，但不强制 (可以访问) s._internal_method() # 输出: 这是一个内部方法 (可以调用) # 尝试直接访问双下划线属性/方法 (会报错 AttributeError) # print(s.__private_stuff) # s.__private_method() # 通过名称改写后的名字访问 (可以访问，但不推荐) print(s._Secretive__private_stuff) # 输出: 这是“私有”的 s._Secretive__private_method() # 输出: 这是一个“私有”方法 # 通过公共方法访问私有属性 print(s.get_private()) # 输出: 这是“私有”的 s.call_private_method() # 输出: 这是一个“私有”方法   类方法与静态方法​  说明: 类方法 (Class Method): 使用 @classmethod 装饰器定义。它的第一个参数是类本身，约定命名为 cls。类方法可以访问和修改类属性，但不能直接访问实例属性（因为它不接收 self）。常用于创建工厂方法（返回类的实例）或操作类级别的状态。静态方法 (Static Method): 使用 @staticmethod 装饰器定义。它不接收 self 或 cls 作为第一个参数，就像一个普通的函数，只是被放在类的命名空间里。静态方法不能访问类属性或实例属性。它通常用于实现与类相关但不需要访问类或实例状态的工具函数。 示例: class Employee: # 类属性 num_of_employees = 0 raise_amount = 1.04 def __init__(self, first, last, pay): self.first = first self.last = last self.pay = pay Employee.num_of_employees += 1 # 修改类属性 def fullname(self): return f&quot;{self.first} {self.last}&quot; def apply_raise(self): self.pay = int(self.pay * self.raise_amount) # 使用实例或类的 raise_amount @classmethod def set_raise_amount(cls, amount): &quot;&quot;&quot;类方法：修改类属性 raise_amount&quot;&quot;&quot; cls.raise_amount = amount print(f&quot;涨薪率已设置为: {cls.raise_amount}&quot;) @classmethod def from_string(cls, emp_str): &quot;&quot;&quot;类方法：工厂方法，从特定格式字符串创建实例&quot;&quot;&quot; first, last, pay = emp_str.split('-') # cls 指向 Employee 类，调用 cls() 等于 Employee() return cls(first, last, int(pay)) @staticmethod def is_workday(day): &quot;&quot;&quot;静态方法：判断某天是否是工作日 (简单示例)&quot;&quot;&quot; # 不访问 self 或 cls if day.weekday() == 5 or day.weekday() == 6: # 周六或周日 return False return True # 使用类方法 Employee.set_raise_amount(1.05) # 通过类调用类方法 # 使用工厂方法创建实例 emp_str_1 = 'John-Doe-70000' emp1 = Employee.from_string(emp_str_1) print(f&quot;
通过字符串创建的员工: {emp1.fullname()}, 工资: {emp1.pay}&quot;) # 使用静态方法 import datetime my_date = datetime.date(2023, 10, 27) # 周五 print(f&quot;
{my_date} 是工作日吗? {Employee.is_workday(my_date)}&quot;) # True my_date = datetime.date(2023, 10, 28) # 周六 print(f&quot;{my_date} 是工作日吗? {Employee.is_workday(my_date)}&quot;) # False print(f&quot;
当前员工总数: {Employee.num_of_employees}&quot;) # 访问类属性   @property 装饰器​  说明: @property 装饰器可以将一个方法变成一个“属性”，使得你可以像访问普通属性一样调用这个方法，而不需要加括号 ()。这常用于： 将计算得到的值包装成属性。实现只读属性。通过 @attribute.setter 和 @attribute.deleter 装饰器为该“属性”提供设置和删除的逻辑，从而控制属性的访问。 示例: class Circle: def __init__(self, radius): if radius &lt; 0: raise ValueError(&quot;半径不能为负数&quot;) self._radius = radius # 使用内部变量存储实际半径 @property def radius(self): &quot;&quot;&quot;获取圆的半径 (只读属性)&quot;&quot;&quot; print(&quot;正在获取半径...&quot;) return self._radius # 如果需要让 radius 可写，可以定义 setter @radius.setter def radius(self, value): &quot;&quot;&quot;设置圆的半径，带验证逻辑&quot;&quot;&quot; print(&quot;正在设置半径...&quot;) if value &lt; 0: raise ValueError(&quot;半径不能为负数&quot;) self._radius = value # 如果需要定义删除逻辑 @radius.deleter def radius(self): &quot;&quot;&quot;删除半径属性 (示例)&quot;&quot;&quot; print(&quot;正在删除半径...&quot;) del self._radius @property def diameter(self): &quot;&quot;&quot;计算直径 (只读，依赖于 radius)&quot;&quot;&quot; return self._radius * 2 @property def area(self): &quot;&quot;&quot;计算面积 (只读，依赖于 radius)&quot;&quot;&quot; import math return math.pi * (self._radius ** 2) c = Circle(5) # 像访问属性一样访问 @property 方法 print(f&quot;圆的半径: {c.radius}&quot;) # 输出: 正在获取半径... 
 圆的半径: 5 print(f&quot;圆的直径: {c.diameter}&quot;) # 输出: 10 print(f&quot;圆的面积: {c.area}&quot;) # 输出: 78.539... # 使用 setter 修改半径 c.radius = 7 # 输出: 正在设置半径... print(f&quot;修改后的半径: {c.radius}&quot;) # 输出: 正在获取半径... 
 修改后的半径: 7 print(f&quot;修改后的面积: {c.area}&quot;) # 输出: 153.938... # 尝试设置无效值 try: c.radius = -1 # 输出: 正在设置半径... 
 ValueError: 半径不能为负数 except ValueError as e: print(f&quot;设置失败: {e}&quot;) # 使用 deleter (如果定义了) # del c.radius # 输出: 正在删除半径... # print(c.radius) # 会报错 AttributeError，因为 _radius 被删了

 单继承与多继承​  说明: 单继承 (Single Inheritance): 一个子类只从一个父类继承。子类会获得父类的所有属性和方法（非私有的）。这是最常见的继承形式。多继承 (Multiple Inheritance): 一个子类可以从多个父类继承，获得所有父类的属性和方法。语法为 class Child(Parent1, Parent2, ...):。多继承可能导致复杂性，特别是“菱形问题”（当多个父类继承自同一个更远的祖先时）。Python 使用 C3 线性化算法来确定方法解析顺序 (MRO - Method Resolution Order)，保证顺序的合理性和一致性。可以通过 ClassName.mro() 或 ClassName.__mro__ 查看 MRO。 示例: # --- 单继承 --- class Animal: def __init__(self, name): self.name = name def eat(self): print(f&quot;{self.name} 正在吃东西...&quot;) # Bird 继承自 Animal class Bird(Animal): def fly(self): print(f&quot;{self.name} 正在飞翔...&quot;) sparrow = Bird(&quot;麻雀&quot;) sparrow.eat() # 继承自 Animal 的方法 sparrow.fly() # Bird 自己的方法 # --- 多继承 --- class Flyer: def fly(self): print(&quot;能够飞翔&quot;) class Swimmer: def swim(self): print(&quot;能够游泳&quot;) # Duck 继承自 Animal, Flyer, Swimmer class Duck(Animal, Flyer, Swimmer): def quack(self): print(f&quot;{self.name}: 嘎嘎嘎!&quot;) donald = Duck(&quot;唐老鸭&quot;) donald.eat() # 来自 Animal donald.fly() # 来自 Flyer (MRO 决定了调用哪个 fly，如果 Animal 也有 fly) donald.swim() # 来自 Swimmer donald.quack() # 来自 Duck # 查看 MRO (方法解析顺序) print(&quot;
Duck 的 MRO:&quot;) print(Duck.mro()) # 输出: [&lt;class '__main__.Duck'&gt;, &lt;class '__main__.Animal'&gt;, &lt;class '__main__.Flyer'&gt;, &lt;class '__main__.Swimmer'&gt;, &lt;class 'object'&gt;] # 这表示查找方法时会按 Duck -&gt; Animal -&gt; Flyer -&gt; Swimmer -&gt; object 的顺序查找   方法重写​  说明: 子类可以提供一个与父类同名的方法，这个过程称为方法重写 (Method Overriding)。当子类对象调用该方法时，会执行子类中的版本，而不是父类中的版本。这允许子类定制或修改继承来的行为。通常，重写的方法签名（参数列表）应与父类保持一致或兼容。可以使用 super() 来调用父类中被重写的方法。 示例: class Parent: def greet(self): print(&quot;来自父类的问候！&quot;) def work(self): print(&quot;父类正在工作...&quot;) class Child(Parent): # 重写 greet 方法 def greet(self): print(&quot;来自子类的问候！&quot;) # 重写 work 方法，并调用父类版本 def work(self): super().work() # 调用父类的 work 方法 print(&quot;子类也完成了一些工作...&quot;) p = Parent() c = Child() p.greet() # 输出: 来自父类的问候！ c.greet() # 输出: 来自子类的问候！ (调用了子类重写的方法) print(&quot;
调用 work 方法:&quot;) p.work() # 输出: # 父类正在工作... c.work() # 输出: # 父类正在工作... # 子类也完成了一些工作... (调用了子类重写的方法，其中包含 super().work())   super()函数​  说明: super() 是一个内置函数，用于调用父类（超类）的方法。它解决了直接调用父类方法时可能遇到的问题（尤其是在多继承中）。 在 __init__ 中，super().__init__(...) 常用于调用父类的构造函数，确保父类部分被正确初始化。在重写的方法中，super().method_name(...) 用于调用父类中被覆盖的同名方法。super() 不需要显式传递 self 或 cls，它会自动找到合适的父类和实例/类。 示例: class Vehicle: def __init__(self, make, model): print(&quot;Vehicle __init__ 被调用&quot;) self.make = make self.model = model def display_info(self): print(f&quot;制造商: {self.make}, 型号: {self.model}&quot;) class Car(Vehicle): def __init__(self, make, model, doors): print(&quot;Car __init__ 被调用&quot;) # 调用父类的 __init__ 方法来初始化 make 和 model super().__init__(make, model) self.doors = doors # 初始化子类特有的属性 # 重写 display_info，并调用父类版本 def display_info(self): print(&quot;--- 汽车信息 ---&quot;) super().display_info() # 调用父类的 display_info print(f&quot;车门数: {self.doors}&quot;) my_car = Car(&quot;丰田&quot;, &quot;卡罗拉&quot;, 4) # 输出: # Car __init__ 被调用 # Vehicle __init__ 被调用 my_car.display_info() # 输出: # --- 汽车信息 --- # 制造商: 丰田, 型号: 卡罗拉 # 车门数: 4   抽象基类(abc 模块)​  说明: 抽象基类 (Abstract Base Class, ABC) 用于定义接口规范。它本身通常不被实例化，而是作为其他类的父类，强制子类必须实现某些特定的方法（称为抽象方法）。使用 abc 模块中的 ABC 作为元类，并使用 @abstractmethod 装饰器标记抽象方法。如果子类没有实现所有抽象方法，那么在尝试实例化子类时会抛出 TypeError。 示例: import abc # 定义一个抽象基类 Shape，需要继承自 abc.ABC class Shape(abc.ABC): @abc.abstractmethod def area(self): &quot;&quot;&quot;计算面积 (抽象方法，子类必须实现)&quot;&quot;&quot; pass @abc.abstractmethod def perimeter(self): &quot;&quot;&quot;计算周长 (抽象方法，子类必须实现)&quot;&quot;&quot; pass def describe(self): # 普通方法，子类可以继承或重写 print(f&quot;这是一个形状，面积: {self.area()}, 周长: {self.perimeter()}&quot;) # 实现 Shape 的子类 Rectangle class Rectangle(Shape): def __init__(self, width, height): self.width = width self.height = height # 必须实现父类的所有抽象方法 def area(self): return self.width * self.height def perimeter(self): return 2 * (self.width + self.height) # 尝试创建抽象基类的实例 (会失败) # shape = Shape() # TypeError: Can't instantiate abstract class Shape ... # 创建子类的实例 rect = Rectangle(5, 3) print(f&quot;矩形面积: {rect.area()}&quot;) # 输出: 15 print(f&quot;矩形周长: {rect.perimeter()}&quot;) # 输出: 16 rect.describe() # 调用继承和实现的方法 # 如果定义一个子类但不实现所有抽象方法 # class Circle(Shape): # def __init__(self, radius): # self.radius = radius # def area(self): # import math # return math.pi * self.radius**2 # # 缺少 perimeter 方法 # # c = Circle(4) # TypeError: Can't instantiate abstract class Circle ...   鸭子类型​  说明: 鸭子类型 (Duck Typing) 是多态的一种形式，它关注对象的行为（能做什么，即有哪些方法和属性）而不是对象的类型（是什么）。&quot;如果它走路像鸭子，叫声像鸭子，那么它就是鸭子&quot;。在 Python 中，这意味着你不必强制要求对象是某个特定类的实例或子类，只要它具有你需要的方法或属性即可。这使得代码更加灵活和解耦。 示例: class Dog: def speak(self): print(&quot;汪汪！&quot;) class Cat: def speak(self): print(&quot;喵喵！&quot;) class Car: # Car 没有 speak 方法 def start_engine(self): print(&quot;引擎启动...&quot;) # 这个函数不关心对象的类型，只关心它是否有 speak 方法 def make_sound(animal): # 尝试调用 speak 方法，如果对象有这个方法就能工作 try: animal.speak() except AttributeError: print(&quot;这个对象不会叫！&quot;) dog = Dog() cat = Cat() car = Car() print(&quot;让动物叫:&quot;) make_sound(dog) # 输出: 汪汪！ make_sound(cat) # 输出: 喵喵！ print(&quot;
尝试让汽车叫:&quot;) make_sound(car) # 输出: 这个对象不会叫！ # 另一个例子：只要对象支持 len() 就能工作 def print_length(obj): try: print(f&quot;对象的长度是: {len(obj)}&quot;) except TypeError: print(&quot;这个对象没有长度！&quot;) print_length([1, 2, 3]) # 列表有 len() print_length(&quot;hello&quot;) # 字符串有 len() print_length({&quot;a&quot;: 1}) # 字典有 len() print_length(123) # 整数没有 len()   Mixin 模式​  说明: Mixin 是一种特殊的多继承用法。Mixin 类通常提供一组特定的、可重用的功能，但它本身不打算被独立实例化，也没有自己的核心状态或父类关系。它通过多继承被“混入”到其他类中，为这些类添加其提供的功能。这有助于代码复用和分离关注点。Mixin 类的命名通常以 Mixin 结尾。 示例: # 定义一个提供日志功能的 Mixin 类 class LoggingMixin: def log(self, message): print(f&quot;日志 [{self.__class__.__name__}]: {message}&quot;) def log_error(self, error_message): print(f&quot;错误 [{self.__class__.__name__}]: {error_message}&quot;) # 定义一个基础类 class DatabaseConnector: def connect(self): print(&quot;连接到数据库...&quot;) # 假设连接成功 def disconnect(self): print(&quot;断开数据库连接...&quot;) # 创建一个混入了 LoggingMixin 的数据库连接类 class LoggingDatabaseConnector(LoggingMixin, DatabaseConnector): # Mixin 通常放在前面 def connect(self): self.log(&quot;尝试连接数据库...&quot;) # 使用 Mixin 提供的 log 方法 try: super().connect() self.log(&quot;数据库连接成功。&quot;) except Exception as e: self.log_error(f&quot;数据库连接失败: {e}&quot;) # 使用 Mixin 提供的 log_error 方法 def execute_query(self, query): self.log(f&quot;执行查询: {query}&quot;) # 假设执行查询... print(f&quot;查询 '{query}' 执行完成。&quot;) # 使用混入后的类 db_conn = LoggingDatabaseConnector() db_conn.connect() # 输出: # 日志 [LoggingDatabaseConnector]: 尝试连接数据库... # 连接到数据库... # 日志 [LoggingDatabaseConnector]: 数据库连接成功。 db_conn.execute_query(&quot;SELECT * FROM users&quot;) # 输出: # 日志 [LoggingDatabaseConnector]: 执行查询: SELECT * FROM users # 查询 'SELECT * FROM users' 执行完成。 db_conn.disconnect() # 输出: # 断开数据库连接...

 init与new​  说明: __new__(cls, ...): 是一个静态方法（虽然不需要 @staticmethod 装饰），负责创建并返回类的实例。它在 __init__ 之前被调用。当你需要控制实例的创建过程时（例如实现单例模式、或者继承自不可变类型如 tuple 或 str 时），才会重写 __new__。它必须返回一个类的实例（通常通过 super().__new__(cls, ...) 创建）。__init__(self, ...): 是实例的初始化方法（构造函数）。它在实例创建后（__new__ 返回实例后）被调用，用于设置实例的初始状态（初始化实例属性）。它不返回值 (或者说，隐式返回 None)。绝大多数情况下，你只需要定义 __init__。 示例: class MyClass: # __new__ 负责创建实例 def __new__(cls, *args, **kwargs): print(&quot;调用 __new__ 方法&quot;) print(f&quot;cls 参数是: {cls}&quot;) # 使用 super() 调用父类 (通常是 object) 的 __new__ 来创建实例 instance = super().__new__(cls) print(f&quot;创建的实例是: {instance}&quot;) return instance # 必须返回实例 # __init__ 负责初始化实例 def __init__(self, value): print(&quot;调用 __init__ 方法&quot;) print(f&quot;self 参数是: {self}&quot;) # self 就是 __new__ 返回的 instance self.value = value print(f&quot;实例属性 value 已设置为: {self.value}&quot;) # 实例化 MyClass obj = MyClass(10) # 输出: # 调用 __new__ 方法 # cls 参数是: &lt;class '__main__.MyClass'&gt; # 创建的实例是: &lt;__main__.MyClass object at 0x...&gt; # 调用 __init__ 方法 # self 参数是: &lt;__main__.MyClass object at 0x...&gt; (与上面地址相同) # 实例属性 value 已设置为: 10 print(f&quot;
对象 obj 的 value: {obj.value}&quot;) # 输出: 10 # 示例：使用 __new__ 实现简单的单例模式 class Singleton: _instance = None # 类属性，存储唯一的实例 def __new__(cls, *args, **kwargs): if cls._instance is None: print(&quot;创建 Singleton 实例...&quot;) cls._instance = super().__new__(cls) else: print(&quot;返回已存在的 Singleton 实例...&quot;) return cls._instance def __init__(self): # 注意：__init__ 每次实例化都会被调用，即使返回的是旧实例 # 可以加个判断防止重复初始化 if not hasattr(self, '_initialized'): print(&quot;初始化 Singleton 实例 (仅一次)...&quot;) self._initialized = True s1 = Singleton() s2 = Singleton() print(f&quot;s1 is s2? {s1 is s2}&quot;) # True   运算符重载(add, eq等)​  说明: Python 允许类通过定义特定的特殊方法（以双下划线开头和结尾）来重载内置运算符。例如，定义 __add__ 方法可以让类的实例支持 + 运算符，定义 __eq__ 方法可以自定义 == 运算符的行为。这使得自定义类的对象可以像内置类型一样自然地使用运算符。 常见可重载运算符及对应方法: +: __add__(self, other)-: __sub__(self, other)*: __mul__(self, other)/: __truediv__(self, other)//: __floordiv__(self, other)%: __mod__(self, other)**: __pow__(self, other)==: __eq__(self, other) (等于)!=: __ne__(self, other) (不等于, 如果没定义，默认是 not __eq__)&lt;: __lt__(self, other) (小于)&gt;: __gt__(self, other) (大于)&lt;=: __le__(self, other) (小于等于)&gt;=: __ge__(self, other) (大于等于)len(): __len__(self)str(): __str__(self) (用户友好的字符串表示)repr(): __repr__(self) (开发者友好的、明确的字符串表示) 示例: class Vector: def __init__(self, x, y): self.x = x self.y = y # 重载 + 运算符 def __add__(self, other): if isinstance(other, Vector): # 返回一个新的 Vector 实例 return Vector(self.x + other.x, self.y + other.y) # 可以选择支持与其他类型的加法，或抛出 TypeError return NotImplemented # 表示此操作未实现，Python 会尝试 other.__radd__(self) # 重载 == 运算符 def __eq__(self, other): if isinstance(other, Vector): return self.x == other.x and self.y == other.y return False # 重载 str() 函数 def __str__(self): # 用户友好的表示 return f&quot;向量({self.x}, {self.y})&quot; # 重载 repr() 函数 def __repr__(self): # 开发者友好的、明确的表示 return f&quot;Vector(x={self.x}, y={self.y})&quot; v1 = Vector(1, 2) v2 = Vector(3, 4) v3 = Vector(1, 2) # 使用重载的运算符 v_sum = v1 + v2 # 调用 v1.__add__(v2) print(f&quot;{v1} + {v2} = {v_sum}&quot;) # 使用 __str__ 输出 # 输出: 向量(1, 2) + 向量(3, 4) = 向量(4, 6) print(f&quot;{v1} == {v2}? {v1 == v2}&quot;) # 调用 v1.__eq__(v2)，输出 False print(f&quot;{v1} == {v3}? {v1 == v3}&quot;) # 调用 v1.__eq__(v3)，输出 True # repr() 通常在交互式环境或打印容器时使用 print([v1, v2]) # 容器内使用 __repr__ # 输出: [Vector(x=1, y=2), Vector(x=3, y=4)]   描述符协议(get, set, delete)​  说明: 描述符 (Descriptor) 是实现了描述符协议的对象。描述符协议包含三个特殊方法：__get__(self, instance, owner)、__set__(self, instance, value) 和 __delete__(self, instance)。当一个类的属性是一个描述符实例时，对该属性的访问（获取、设置、删除）会被这些特殊方法拦截。 __get__: 在获取属性值时调用。instance 是拥有该属性的实例，owner 是拥有该属性的类。__set__: 在设置属性值时调用。__delete__: 在删除属性时调用。 描述符允许将属性访问逻辑封装在一个单独的类中，常用于实现属性验证、延迟加载、方法装饰器（如 @property, @classmethod, @staticmethod 都是基于描述符实现的）等。 分为数据描述符（实现了 __set__ 或 __delete__）和非数据描述符（只实现了 __get__）。数据描述符优先级高于实例字典。 示例: # 一个简单的数据验证描述符 class NonNegative: def __init__(self, name): self.name = name # 描述符实例知道它在宿主类中的名字 def __get__(self, instance, owner): if instance is None: # 通过类访问描述符时，instance 为 None return self # 返回存储在实例字典中的值 # print(f&quot;正在获取 {self.name}...&quot;) return instance.__dict__.get(self.name) def __set__(self, instance, value): # print(f&quot;正在设置 {self.name}...&quot;) if not isinstance(value, (int, float)) or value &lt; 0: raise ValueError(f&quot;{self.name} 必须是非负数字&quot;) # 将值存储在实例的字典中 instance.__dict__[self.name] = value def __delete__(self, instance): # print(f&quot;正在删除 {self.name}...&quot;) instance.__dict__.pop(self.name, None) class Product: # 将描述符实例作为类属性 price = NonNegative('price') quantity = NonNegative('quantity') def __init__(self, name, price, quantity): self.name = name # 设置属性时会调用描述符的 __set__ self.price = price self.quantity = quantity def total_cost(self): # 获取属性时会调用描述符的 __get__ return self.price * self.quantity # 创建实例 p1 = Product(&quot;苹果&quot;, 5.5, 10) print(f&quot;产品: {p1.name}, 价格: {p1.price}, 数量: {p1.quantity}&quot;) print(f&quot;总成本: {p1.total_cost()}&quot;) # 尝试设置无效值 try: p1.price = -2 # 会触发 NonNegative.__set__ 的验证 except ValueError as e: print(f&quot;设置价格失败: {e}&quot;) # 设置价格失败: price 必须是非负数字 # 删除属性 (如果描述符实现了 __delete__) # del p1.quantity # print(p1.quantity) # None (如果 get 处理了不存在的情况) or AttributeError   上下文管理协议(enter, exit)​  说明: 上下文管理协议允许对象与 with 语句一起使用。with 语句提供了一种确保资源（如文件、网络连接、锁）被正确管理（即使发生异常也能自动清理）的方式。要成为上下文管理器，对象必须实现两个方法： __enter__(self): 在进入 with 语句块之前调用。它的返回值（如果有）会赋给 as 子句后面的变量。通常用于执行设置操作或返回要使用的资源。__exit__(self, exc_type, exc_val, exc_tb): 在退出 with 语句块时（无论正常退出还是因异常退出）调用。 exc_type: 异常类型（如果发生异常）。exc_val: 异常实例（如果发生异常）。exc_tb: 异常追踪信息 (traceback)（如果发生异常）。 如果 with 块正常退出，这三个参数都为 None。__exit__ 方法负责执行清理操作。如果它返回 True，表示异常已被处理，不会继续向外传播；如果返回 False 或 None（默认），异常会继续传播。 示例: (之前 Timer 的例子很好，这里再给一个资源的例子) class ManagedResource: def __init__(self, name): self.name = name self.acquired = False print(f&quot;资源 '{self.name}' 初始化&quot;) def __enter__(self): &quot;&quot;&quot;进入 with 块：获取资源&quot;&quot;&quot; print(f&quot;正在获取资源 '{self.name}'...&quot;) # 模拟获取资源的操作 self.acquired = True print(f&quot;资源 '{self.name}' 已获取&quot;) return self # 返回自身，可以在 as 子句中使用 def __exit__(self, exc_type, exc_val, exc_tb): &quot;&quot;&quot;退出 with 块：释放资源&quot;&quot;&quot; print(f&quot;
正在释放资源 '{self.name}'...&quot;) # 模拟释放资源的操作 self.acquired = False print(f&quot;资源 '{self.name}' 已释放&quot;) if exc_type is not None: # 如果有异常发生 print(f&quot; 在 with 块中发生异常:&quot;) print(f&quot; 类型: {exc_type.__name__}&quot;) print(f&quot; 值: {exc_val}&quot;) # 返回 False (或 None) 让异常继续传播 # return True # 如果想抑制异常，返回 True else: print(&quot; with 块正常结束&quot;) return False # 默认行为，不抑制异常 def use(self): if self.acquired: print(f&quot;正在使用资源 '{self.name}'...&quot;) else: print(f&quot;错误：资源 '{self.name}' 未获取！&quot;) print(&quot;--- 使用 ManagedResource ---&quot;) try: with ManagedResource(&quot;网络连接&quot;) as conn: conn.use() # 模拟在 with 块中发生错误 # result = 1 / 0 print(&quot;完成资源使用&quot;) except Exception as e: print(f&quot;
在 with 外部捕获到异常: {e}&quot;) print(&quot;
--- 演示异常处理 ---&quot;) try: with ManagedResource(&quot;数据库锁&quot;) as lock: lock.use() raise ValueError(&quot;操作失败&quot;) # 在 with 块中手动引发异常 print(&quot;这行不会执行&quot;) except ValueError as e: print(f&quot;
在 with 外部捕获到 ValueError: {e}&quot;)   迭代器协议(iter, next)​  说明: 迭代器协议是 Python 中 for 循环工作的基础。一个对象要成为可迭代对象 (Iterable)，它必须实现 __iter__ 方法，该方法返回一个迭代器对象 (Iterator)。迭代器对象负责逐个产生序列中的元素，它必须实现两个方法： __iter__(self): 返回迭代器对象自身（通常就是 return self）。__next__(self): 返回序列中的下一个元素。当没有更多元素时，必须引发 StopIteration 异常。 示例: # 实现一个可迭代的倒计时类 class Countdown: def __init__(self, start): self.current = start # 使 Countdown 对象可迭代 def __iter__(self): # 返回迭代器对象 (自身) print(&quot;调用 Countdown 的 __iter__&quot;) return self # 实现迭代器的 __next__ 方法 def __next__(self): print(&quot;调用 Countdown 的 __next__&quot;) if self.current &lt;= 0: # 没有更多元素，引发 StopIteration print(&quot;引发 StopIteration&quot;) raise StopIteration else: # 返回当前值，并将计数减 1 value = self.current self.current -= 1 return value print(&quot;--- 使用 for 循环迭代 Countdown(3) ---&quot;) # for 循环会自动调用 __iter__ 获取迭代器，然后反复调用 __next__ for i in Countdown(3): print(f&quot;循环得到: {i}&quot;) print(&quot;
--- 手动迭代 Countdown(2) ---&quot;) countdown_iter = iter(Countdown(2)) # 等价于 Countdown(2).__iter__() try: print(f&quot;手动 next 1: {next(countdown_iter)}&quot;) # 等价于 countdown_iter.__next__() print(f&quot;手动 next 2: {next(countdown_iter)}&quot;) print(f&quot;手动 next 3: {next(countdown_iter)}&quot;) # 这里会引发 StopIteration except StopIteration: print(&quot;手动迭代捕获到 StopIteration&quot;) # 输出示例: # --- 使用 for 循环迭代 Countdown(3) --- # 调用 Countdown 的 __iter__ # 调用 Countdown 的 __next__ # 循环得到: 3 # 调用 Countdown 的 __next__ # 循环得到: 2 # 调用 Countdown 的 __next__ # 循环得到: 1 # 调用 Countdown 的 __next__ # 引发 StopIteration # # --- 手动迭代 Countdown(2) --- # 调用 Countdown 的 __iter__ # 调用 Countdown 的 __next__ # 手动 next 1: 2 # 调用 Countdown 的 __next__ # 手动 next 2: 1 # 调用 Countdown 的 __next__ # 引发 StopIteration # 手动迭代捕获到 StopIteration   属性访问控制(getattr, setattr)​  说明: 这些特殊方法允许你拦截对对象属性的访问、赋值和删除操作。 __getattr__(self, name): 仅当尝试访问的属性 name 不存在于实例、类或其父类中时才会被调用。常用于实现动态属性、代理或向后兼容。__setattr__(self, name, value): 每次对属性 name 进行赋值操作时（instance.name = value）都会被调用。在 __setattr__ 内部给属性赋值时，必须使用 object.__setattr__(self, name, value) 或直接操作 self.__dict__ 来避免无限递归。__getattribute__(self, name): 每次访问属性 name 时（无论属性是否存在）都会被调用。这比 __getattr__ 更底层，但也更容易引起无限递归，因此使用时要特别小心。通常在 __getattribute__ 内部需要通过 object.__getattribute__(self, name) 来获取属性值。__delattr__(self, name): 每次使用 del instance.name 删除属性时调用。同样，在内部删除属性需用 object.__delattr__(self, name) 或操作 self.__dict__。 示例: class DynamicAttributes: def __init__(self): self._attributes = {'default_attr': '默认值'} # __getattr__ 只在属性未找到时调用 def __getattr__(self, name): print(f&quot;调用 __getattr__ 查找属性: {name}&quot;) if name in self._attributes: return self._attributes[name] else: # 如果连动态查找也找不到，通常引发 AttributeError raise AttributeError(f&quot;'{type(self).__name__}' 对象没有属性 '{name}'&quot;) # __setattr__ 每次赋值都调用 def __setattr__(self, name, value): print(f&quot;调用 __setattr__: 设置 {name} = {value}&quot;) # 如果是内部使用的 _attributes，直接用 object.__setattr__ 设置 if name == '_attributes': object.__setattr__(self, name, value) else: # 其他属性存入 _attributes 字典 self._attributes[name] = value # __getattribute__ 每次访问都调用 (需小心使用) # def __getattribute__(self, name): # print(f&quot;调用 __getattribute__ 访问: {name}&quot;) # # 必须用 object.__getattribute__ 来获取，否则无限递归 # return object.__getattribute__(self, name) dyn = DynamicAttributes() # 访问存在的属性 (存放在 _attributes 中，通过 __getattr__ 找到) print(f&quot;访问 default_attr: {dyn.default_attr}&quot;) # 输出: # 调用 __getattr__ 查找属性: default_attr # 访问 default_attr: 默认值 # 访问不存在的属性 (触发 __getattr__ 但找不到) try: print(dyn.non_existent) except AttributeError as e: print(f&quot;访问 non_existent 失败: {e}&quot;) # 输出: # 调用 __getattr__ 查找属性: non_existent # 访问 non_existent 失败: 'DynamicAttributes' 对象没有属性 'non_existent' # 设置属性 (触发 __setattr__) dyn.new_attr = &quot;新值&quot; # 输出: 调用 __setattr__: 设置 new_attr = 新值 # 访问新设置的属性 (通过 __getattr__ 找到) print(f&quot;访问 new_attr: {dyn.new_attr}&quot;) # 输出: # 调用 __getattr__ 查找属性: new_attr # 访问 new_attr: 新值 # 查看内部字典 print(f&quot;内部字典 _attributes: {dyn._attributes}&quot;) # 输出: 内部字典 _attributes: {'default_attr': '默认值', 'new_attr': '新值'}

