所有项:&quot;) for key, value in db.items(): print(f&quot; {key}: {value}&quot;) # 获取修改后的 counter counter_val = db.get('counter', 0) # 使用 get 获取，提供默认值 print(f&quot;
Counter 值: {counter_val}&quot;) # 应该是 101 # 获取修改后的 user2 user2_read = db['user2'] print(f&quot;
修改后的 User2: {user2_read}&quot;) # hobbies 应包含 '阅读' except Exception as e: print(f&quot;读取 shelf 文件失败: {e}&quot;) # 清理 (如果需要) # import glob, os # for f in glob.glob(shelf_file + '*'): # os.remove(f) # print(f&quot;
Shelf 文件 {shelf_file}* 已删除。&quot;)   自定义序列化​  说明: 当使用 pickle 或 json 等模块序列化自定义类的实例时，可能需要自定义序列化过程。 对于 pickle: 可以定义 __getstate__(self) 方法：该方法应返回一个可被 pickle 的对象（通常是包含实例状态的字典），pickle 将序列化这个返回的对象而不是实例的 __dict__。可以定义 __setstate__(self, state) 方法：反序列化时，pickle 会创建一个未初始化的实例，然后调用 __setstate__ 并传入 __getstate__ 返回（或旧版本 pickle 的 __dict__）的状态 state。你需要在 __setstate__ 中使用 state 来恢复实例的状态。 对于 json: 序列化：在调用 json.dumps() 或 json.dump() 时提供一个 default 函数。当遇到 JSON 不认识的对象时，会调用 default(obj)，该函数应返回一个 JSON 可序列化的表示（如字典）。反序列化：在调用 json.loads() 或 json.load() 时提供一个 object_hook 函数。该函数会在每个 JSON 对象（字典）被解码后调用，传入解码后的字典，函数可以检查字典内容并返回相应的自定义对象实例。 示例: (使用 JSON 自定义序列化) import json class ComplexNumber: def __init__(self, real, imag): self.real = real self.imag = imag def __repr__(self): return f&quot;ComplexNumber({self.real}, {self.imag}j)&quot; # --- 自定义 JSON 序列化 (使用 default 函数) --- def complex_encoder(obj): if isinstance(obj, ComplexNumber): # 返回一个 JSON 可序列化的字典表示 return {'__complex__': True, 'real': obj.real, 'imag': obj.imag} # 对于其他类型，让默认编码器处理或抛出 TypeError raise TypeError(f&quot;对象类型 {type(obj)} 不能被 JSON 序列化&quot;) c1 = ComplexNumber(3, 4) data_with_complex = {'number': c1, 'label': '示例复数'} try: json_string = json.dumps(data_with_complex, default=complex_encoder, indent=2) print(&quot;--- 自定义 JSON 序列化 ---&quot;) print(json_string) # 输出: # { # &quot;number&quot;: { # &quot;__complex__&quot;: true, # &quot;real&quot;: 3, # &quot;imag&quot;: 4 # }, # &quot;label&quot;: &quot;示例复数&quot; # } except TypeError as e: print(f&quot;JSON 序列化失败: {e}&quot;) # --- 自定义 JSON 反序列化 (使用 object_hook 函数) --- def complex_decoder(dct): # 检查字典是否包含我们添加的特殊标记 if '__complex__' in dct: # 如果是，创建 ComplexNumber 实例并返回 return ComplexNumber(dct['real'], dct['imag']) # 否则，返回原始字典 return dct if 'json_string' in locals(): try: loaded_data = json.loads(json_string, object_hook=complex_decoder) print(&quot;
--- 自定义 JSON 反序列化 ---&quot;) print(loaded_data) # 输出: {'number': ComplexNumber(3, 4j), 'label': '示例复数'} print(f&quot;反序列化后 number 的类型: {type(loaded_data.get('number'))}&quot;) # 输出: &lt;class '__main__.ComplexNumber'&gt; except Exception as e: print(f&quot;JSON 反序列化失败: {e}&quot;)

 StringIO 与 BytesIO​  说明: io 模块提供了 StringIO 和 BytesIO 类，它们创建行为类似文件的内存中缓冲区。这在需要将数据作为文件处理但不想实际写入磁盘时非常有用（例如，测试、数据转换、与其他期望文件对象的库交互）。 io.StringIO: 用于处理文本数据（字符串）。它的行为像一个以文本模式打开的文件。io.BytesIO: 用于处理二进制数据（字节串）。它的行为像一个以二进制模式打开的文件。 它们都支持文件对象的大部分方法，如 read(), write(), seek(), tell(), getvalue()（获取缓冲区全部内容）。 示例: import io # --- StringIO 示例 (内存中的文本文件) --- # 创建一个 StringIO 对象 string_buffer = io.StringIO() # 像文件一样写入字符串 string_buffer.write(&quot;第一行文本。
&quot;) string_buffer.write(&quot;这是第二行。
&quot;) # 获取缓冲区中的全部内容 print(&quot;--- StringIO ---&quot;) all_content = string_buffer.getvalue() print(f&quot;getvalue() 获取的内容:
{all_content}&quot;) # 移动指针到开头以便读取 string_buffer.seek(0) # 像文件一样读取 line1 = string_buffer.readline() print(f&quot;readline() 读取的第一行: {line1.strip()}&quot;) remaining_content = string_buffer.read() print(f&quot;read() 读取剩余内容:
{remaining_content}&quot;) # 关闭缓冲区 (虽然对于内存缓冲区不是必须，但好习惯) string_buffer.close() # --- BytesIO 示例 (内存中的二进制文件) --- # 创建一个 BytesIO 对象 bytes_buffer = io.BytesIO() # 写入字节数据 bytes_buffer.write(b'\x01\x02\x03') bytes_buffer.write(b'Hello') # 获取缓冲区中的全部字节 print(&quot;
--- BytesIO ---&quot;) all_bytes = bytes_buffer.getvalue() print(f&quot;getvalue() 获取的字节: {all_bytes}&quot;) # b'\x01\x02\x03Hello' # 移动指针到开头 bytes_buffer.seek(0) # 读取字节 first_3_bytes = bytes_buffer.read(3) print(f&quot;读取前 3 字节: {first_3_bytes}&quot;) # b'\x01\x02\x03' rest_bytes = bytes_buffer.read() print(f&quot;读取剩余字节: {rest_bytes}&quot;) # b'Hello' bytes_buffer.close() # 应用：将数据写入内存缓冲区，再传递给需要文件对象的函数 def process_file_content(file_obj): print(f&quot;
[process_file_content] 读取内容: {file_obj.read()}&quot;) in_memory_file = io.StringIO(&quot;这是来自 StringIO 的数据&quot;) process_file_content(in_memory_file) in_memory_file.close()   文件压缩(gzip, zipfile)​  说明: Python 标准库提供了处理常见压缩格式的模块。 gzip: 用于处理 .gz 文件（GNU zip 格式），通常用于压缩单个文件。它提供了类似文件对象的接口 (gzip.open())，可以方便地在读写时进行压缩和解压缩。zipfile: 用于处理 .zip 文件（ZIP 归档格式），可以包含多个文件和目录。ZipFile 类提供了创建、读取、写入和提取 ZIP 文件的功能。 示例: import gzip import zipfile import os original_file = 'my_document.txt' gz_file = 'my_document.txt.gz' zip_file = 'my_archive.zip' content_to_compress = b&quot;This is the content to be compressed. &quot; * 5 # --- 使用 gzip 压缩和解压缩单个文件 --- print(&quot;--- gzip 示例 ---&quot;) # 压缩文件 try: with gzip.open(gz_file, 'wb') as f_gz: # 以二进制写模式打开 gzip 文件 f_gz.write(content_to_compress) print(f&quot;内容已压缩到 {gz_file}&quot;) except Exception as e: print(f&quot;gzip 压缩失败: {e}&quot;) # 解压缩文件 try: with gzip.open(gz_file, 'rb') as f_gz: # 以二进制读模式打开 gzip 文件 decompressed_content = f_gz.read() print(f&quot;从 {gz_file} 解压缩内容 (部分): {decompressed_content[:50]}...&quot;) print(f&quot;解压内容与原文是否一致? {decompressed_content == content_to_compress}&quot;) except FileNotFoundError: print(f&quot;文件 {gz_file} 不存在，无法解压。&quot;) except Exception as e: print(f&quot;gzip 解压失败: {e}&quot;) # --- 使用 zipfile 创建和解压 ZIP 归档 --- print(&quot;
--- zipfile 示例 ---&quot;) # 创建 ZIP 文件并添加文件 file1_content = b&quot;Content for file one.&quot; file2_content = b&quot;Content for file two inside a folder.&quot; file1_name = 'file1.txt' file2_name_in_zip = 'folder/file2.txt' # 在 zip 中创建目录结构 try: with zipfile.ZipFile(zip_file, 'w', compression=zipfile.ZIP_DEFLATED) as zf: # 'w' 创建， ZIP_DEFLATED 是常用压缩算法 # 方法一：从字符串写入 zf.writestr(file1_name, file1_content) zf.writestr(file2_name_in_zip, file2_content) # 方法二：从现有文件写入 (假设先创建了 original_file) with open(original_file, 'wb') as f_orig: f_orig.write(content_to_compress) zf.write(original_file, arcname='renamed_document.txt') # arcname 指定在 zip 中的名字 print(f&quot;文件已添加到 {zip_file}&quot;) # 列出 ZIP 文件内容 with zipfile.ZipFile(zip_file, 'r') as zf: print(f&quot;
{zip_file} 中的文件列表:&quot;) zf.printdir() # 读取 ZIP 文件中的某个文件 with zipfile.ZipFile(zip_file, 'r') as zf: print(f&quot;
读取 {file1_name} 的内容:&quot;) content1 = zf.read(file1_name) print(content1) # 解压 ZIP 文件 extract_dir = 'extracted_files' if not os.path.exists(extract_dir): os.makedirs(extract_dir) with zipfile.ZipFile(zip_file, 'r') as zf: zf.extractall(path=extract_dir) # 解压所有文件到指定目录 # zf.extract('file1.txt', path=extract_dir) # 解压单个文件 print(f&quot;
{zip_file} 已解压到 {extract_dir}&quot;) except Exception as e: print(f&quot;zipfile 操作失败: {e}&quot;) # 清理示例文件 # if os.path.exists(original_file): os.remove(original_file) # if os.path.exists(gz_file): os.remove(gz_file) # if os.path.exists(zip_file): os.remove(zip_file) # import shutil # if os.path.exists(extract_dir): shutil.rmtree(extract_dir)   CSV 文件处理​  说明: CSV (Comma-Separated Values) 是一种常见的纯文本格式，用于存储表格数据。每行代表一条记录，记录内的字段（列）通常用逗号分隔。csv 模块提供了处理 CSV 文件的功能，能够正确处理包含逗号、引号或换行符的字段。 csv.reader(csvfile, dialect='excel', **fmtparams): 创建一个 reader 对象，用于迭代 CSV 文件 csvfile 中的行。每行返回一个字符串列表。csv.writer(csvfile, dialect='excel', **fmtparams): 创建一个 writer 对象，用于将数据写入 CSV 文件 csvfile。 writerow(row): 写入单行（row 应是一个列表或元组）。writerows(rows): 写入多行（rows 应是一个可迭代对象，其中每个元素是表示一行的列表或元组）。 csv.DictReader: 类似 csv.reader，但将每行解析为字典，键来自文件的第一行（表头）。csv.DictWriter: 类似 csv.writer，但接受字典列表作为输入，需要指定 fieldnames (表头)。注意: csv 模块默认处理文本文件，打开文件时应指定 encoding 和 newline='' (官方推荐)。 示例: import csv csv_file = 'data.csv' data_to_write = [ ['姓名', '年龄', '城市'], # 表头 ['张三', 30, '北京'], ['李四', 25, '上海,中国'], # 包含逗号的字段 ['王五', 35, '广州'] ] # --- 使用 csv.writer 写入数据 --- try: # newline='' 防止写入多余空行 (尤其在 Windows) with open(csv_file, 'w', newline='', encoding='utf-8') as f: writer = csv.writer(f) # writer.writerow(data_to_write[0]) # 写入单行表头 # writer.writerows(data_to_write[1:]) # 写入数据行 writer.writerows(data_to_write) # 一次性写入所有行 print(f&quot;数据已使用 csv.writer 写入到 {csv_file}&quot;) except Exception as e: print(f&quot;写入 CSV 文件失败: {e}&quot;) # --- 使用 csv.reader 读取数据 --- try: with open(csv_file, 'r', newline='', encoding='utf-8') as f: reader = csv.reader(f) print(&quot;
--- 使用 csv.reader 读取数据 ---&quot;) header = next(reader) # 读取表头 print(f&quot;表头: {header}&quot;) for row in reader: # 迭代数据行 print(f&quot;数据行: {row}&quot;) # 输出是列表 ['李四', '25', '上海,中国'] except FileNotFoundError: print(f&quot;
文件 {csv_file} 不存在，无法读取。&quot;) except Exception as e: print(f&quot;
